quests[56034] = { id = 56034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Probleme brauchen größere Lösungen", description = "Der Größenänderer v9.0.1 funktioniert schon kaum an leblosen Dingen, seinen Effekt auf organische Materie kann ich kaum abschätzen!\n\nWenn wir aber gar nichts tun, wird Furorion sterben!\n\nVerzweifelte Zeiten erfordern eben äußerst experimentelle Wissenschaft, {name}.\n\nNehmt den Größenänderer v9.0.1. Ich werde Euch folgen und ihn kalibrieren.\n\nWir werden einen riesigen Eber erschaffen!", sourceObjective = "Setzt den Größenänderer v9.0.1 bei 3 wandernden Ebern ein.", progress = "Passt bloß auf, worauf Ihr den Größenänderer v9.0.1 richtet. Benutzt ihn nur an den Ebern in der unmittelbaren Umgebung.", completion = "Ich hätte nie erwartet, dass ich mal so froh sein würde, einem durch Wissenschaft vergrößerten Eber gegenüberzustehen.\n\nUnd jetzt lasst uns meinen Sohn retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56035] = { id = 56035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheldelikatesse", description = "Dieses Becken ist voller unheimlicher Fische.\n\nEs ist außerdem die Heimat der delikatesten Muscheln, die Ihr je kosten werdet. In diesem Teil von Nazjatar mischt sich Süßwasser mit Meerwasser. Dadurch bekommt das Fleisch einen völlig neuartigen Geschmack.\n\nAb und zu kommen wir hier herunter und sammeln sie für unsere Freunde in Neuheim.\n\nWir könnten wirklich Eure Hilfe brauchen, bei all den zusätzlichen Mäulern, die es zu stopfen gilt!", sourceObjective = "Sammelt 10 neptulische Muscheln.", progress = "Habt Ihr genug gefunden?", completion = "Alle werden so glücklich sein!\n\nVielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[56036] = { id = 56036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dampfende Angelegenheit" }
quests[56037] = { id = 56037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagageheimnisse stehlen", description = "<Bei näherem Hinsehen wird deutlich, dass die Klingen aus Azerit geschmiedet wurden.\n\nWaffen mit solchen Kräften sollten niemals in die Hände der Naga gelangen.>", sourceObjective = "Stehlt die Azeritwaffen und kämpft Euch den Weg von der Terrasse der Zanj'ir frei!", progress = "Ich erkenne diese Handwerkskunst. Das ist die Arbeit von Priscilla Aschenwind.\n\nSie muss den Naga beigebracht haben, wie man Azeritwaffen schmiedet, aber warum?", completion = "Wir können nicht erwarten, irgendeinen Kampf zu gewinnen, wenn unsere Feinde Azeritwaffen benutzen.\n\nNein, wir müssen einen Weg finden, die Chancen auszugleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56038] = { id = 56038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweckgerichtet arbeiten", description = "Anscheinend sind die Shirakess nie zufrieden mit der Anzahl Perlen, die wir ihnen beschaffen. Sie verlangen immer noch mehr.\n\nBevor Ihr gekommen seid, war es meine Aufgabe, in der Höhle herumzukriechen und Muscheln aufzubrechen.\n\nIhr seht also, Ihr habt einen Zweck und seid nicht nur ein nutzloser Sack Fleisch.", sourceObjective = "Sammelt 6 schillernde Perlen von Zitterschalenmuscheln.", progress = "Habt Ihr sie alle?", completion = "Ihr seid darum bemüht, jeden Wunsch zu erfüllen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[56039] = { id = 56039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stumpfe Waffen taugen nichts", description = "Dafür, dass Ihr ein Tintenfischkopf seid, macht Ihr mir das Leben wirklich leichter.\n\nIch schätze, Ihr werdet lange genug leben, um eine weitere Aufgabe zu erledigen.\n\nUnsere neuen Waffen wurden aus einem fremdartigen Material geschmiedet, dem ich nicht so richtig traue.\n\nIhr werdet nicht erleben, dass ich die Klingen selbst schärfe, aber die Arbeit muss getan werden.\n\nMacht Euch an die Arbeit!", sourceObjective = "Findet die Spezialwaffen innerhalb der Terrasse der Zanj'ir.", completion = "<Die Waffen in der Halterung strahlen eine Euch wohlbekannte Energie aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56041] = { id = 56041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht miese Muscheln munter" }
quests[56042] = { id = 56042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 7000", sourceObjective = "AUSGABE: Bitte akzeptiert dieses GESCHENK.\n\nGESCHENKVERTEILUNGSPROTOKOLL INITIIERT.", sourceObjectiveStatus = "unverified-source-field" }
quests[56043] = { id = 56043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schickt die Flotte", description = "Dieser Krieg hat uns viel abverlangt, aber der Sieg ist zum Greifen nahe.\n\nDer Rest der Hordenflotte hat Zuldazar verlassen, und unsere Spione berichten, dass die Hand der Bansheekönigin an ihrer Spitze segelt.\n\nDas ist unsere Chance, {name}! Wir können mit einem Schlag den Rest ihrer Flotte erledigen und Azeroth ein für alle Mal von Pestrufers Abschaum befreien!\n\nDie Flotte bereitet sich auf den Aufbruch vor. Meldet Euch beim Hafenmeister, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Hafenmeister Carsten Jammerthal, um die Segel zu setzen.", completion = "Das hätte ich niemals erwartet...", sourceObjectiveStatus = "unverified-source-field" }
quests[56044] = { id = 56044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schickt die Flotte", description = "Der Kriegshäuptling hat mich mit einer Mission höchster Priorität beauftragt, {name}.\n\nOhne Frage wird diese Mission erfolgreich sein. Aber ich muss sicherstellen, dass alle Hindernisse in meinem Weg schnell beseitigt werden. Deswegen brauche ich erneut Eure einzigartigen Fertigkeiten.\n\nDie Zandalari haben angeboten, uns für dieses Vorhaben ihre Schiffe benutzen zu lassen. Erledigt Eure Aufgaben hier und meldet Euch bei Käpt'n Rez'okun, wenn Ihr bereit seid, die Segel zu setzen.", sourceObjective = "Sprecht mit Käpt'n Rez'okun, um die Segel zu setzen.", completion = "Eine unerwartete Entwicklung, aber das ändert nichts.\n\nWir haben unsere Befehle, die es auszuführen gilt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56045] = { id = 56045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagageheimnisse stehlen", description = "<Bei näherem Hinsehen wird deutlich, dass die Klingen aus Azerit geschmiedet wurden.\n\nWaffen mit solchen Kräften sollten niemals in die Hände der Naga gelangen.>", sourceObjective = "Stehlt die Azeritwaffen und kämpft Euch den Weg von der Terrasse der Zanj'ir frei!", progress = "Ich erkenne diese Handwerkskunst. Das ist die Arbeit von Priscilla Aschenwind.\n\nSie muss den Naga beigebracht haben, wie man Azeritwaffen schmiedet, aber warum?", completion = "Wir können nicht erwarten, irgendeinen Kampf zu gewinnen, wenn unsere Feinde Azeritwaffen benutzen.\n\nNein, wir müssen einen Weg finden, die Chancen auszugleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56046] = { id = 56046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweckgerichtet arbeiten", description = "Anscheinend sind die Shirakess nie zufrieden mit der Anzahl Perlen, die wir ihnen beschaffen. Sie verlangen immer noch mehr.\n\nBevor Ihr gekommen seid, war es meine Aufgabe, in der Höhle herumzukriechen und Muscheln aufzubrechen.\n\nIhr seht also, Ihr habt einen Zweck und seid nicht nur ein nutzloser Sack Fleisch.", sourceObjective = "Sammelt 6 schillernde Perlen von Zitterschalenmuscheln.", progress = "Habt Ihr sie alle?", completion = "Ihr seid darum bemüht, jeden Wunsch zu erfüllen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[56047] = { id = 56047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stumpfe Waffen taugen nichts", description = "Dafür, dass Ihr ein Tintenfischkopf seid, macht Ihr mir das Leben wirklich leichter.\n\nIch schätze, Ihr werdet lange genug leben, um eine weitere Aufgabe zu erledigen.\n\nUnsere neuen Waffen wurden aus einem fremdartigen Material geschmiedet, dem ich nicht so richtig traue.\n\nIhr werdet nicht erleben, dass ich die Klingen selbst schärfe, aber die Arbeit muss getan werden.\n\nMacht Euch an die Arbeit!", sourceObjective = "Findet die Spezialwaffen innerhalb der Terrasse der Zanj'ir.", completion = "<Die Waffen in der Halterung strahlen eine Euch wohlbekannte Energie aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56048] = { id = 56048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ertrunkenen Orakel" }
quests[56049] = { id = 56049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingedeckt", description = "Dieser Schleim scheint wirklich hungrig zu sein!\n\nEr hat meinen Rucksack gefressen, meinen Kompass, meine Spitzhacke und meine Hearthstone-Karten.\n\nHolt mir meine Karten zurück!", sourceObjective = "Bringt Adalins Hearthstone-Karten zurück.", progress = "Ich gehe erst, wenn ich meine Karten zurückhabe!", completion = "Danke! Ich schnappe mir jetzt meine Karten und wir sehen uns in der Stadt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56050] = { id = 56050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "PvP-Ereignis: Schlacht um Nazjatar" }
quests[56053] = { id = 56053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Akt", description = "Diejenigen von uns, die ausreichend mechanisiert waren, überlebten, aber das war egal. Bondo Brummblock hat uns verraten. Als Gegenleistung für seine vollständige Mechanisierung hat er riesige Bots gebaut und den Rostbolzen angegriffen.\n\nEr wird so lange weitermachen, bis der Rest von uns auch tot ist.\n\nDiese Bedrohung muss sofort beseitigt werden.", sourceObjective = "Tötet Bondo Brummblock.", progress = "Werdet Ihr mir bei der Beseitigung dieser Bedrohung helfen?", completion = "Jetzt können wir mit dem Wiederaufbau beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56056] = { id = 56056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken der Tiefe" }
quests[56057] = { id = 56057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenbinder" }
quests[56063] = { id = 56063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gezeiten", description = "Eine Gezeitenherrin kommandiert die Naga in diesem Gebiet.\n\nSie führt draußen irgendein verwerfliches Ritual aus, das Opfer unter unseren Soldaten fordert.\n\nHaltet sie auf, bevor noch mehr unserer Leute ein so schlimmes Schicksal ereilt.", sourceObjective = "Tötet Gezeitenherrin Ethendriss.", completion = "Ihr Tod hat das Ritual beendet, aber zum Feiern ist keine Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[56064] = { id = 56064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Das Schwarze Imperium", description = "Ich traue meinen Augen kaum. Das Schwarze Imperium tritt direkt hier im Tal in Erscheinung!\n\nWir müssen sofort handeln!", sourceObjective = "Schlagt den Angriff von N'Zoth im Tal der Ewigen Blüten zurück.", completion = "Zum Glück seid Ihr gerade zur rechten Zeit eingetroffen! Ich kann immer noch nicht glauben, dass N'Zoth genau hier vor meiner Haustür zuschlagen wollte.\n\nDie Pandaren werden diese Geschichte über zahllose Generationen hinweg erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56070] = { id = 56070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Venthyr", description = "Graf Denathrius steht im Bann des Kerkermeisters. Er wird für seinen Verrat an unserem Volk bezahlen.\n\nWir werden dem Kerkermeister zeigen, dass man die Venthyr nicht unterschätzen sollte... und Euch auch nicht, <Schlundgänger/Schlundgängerin>. Tötet seine Leutnants. Zeigt ihm, dass er jetzt der Gejagte ist.", sourceObjective = "Besiegt die Leutnants des Kerkermeisters auf Stock 5 und 10 des Turms des Kerkermeisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[56071] = { id = 56071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desynchronisierte Vibroklinge", description = "Die wild bebende Klinge erinnert Euch an die Schwerter der Rostbolzenverteidiger. Zweifellos wird jemand sie reparieren können.", sourceObjective = "Gebt die desynchronisierte Vibroklinge Ricket im Rostbolzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56072] = { id = 56072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desynchronisierte Vibroklinge", description = "Die wild bebende Klinge erinnert Euch an die Schwerter der Rostbolzenverteidiger. Zweifellos wird jemand sie reparieren können.", sourceObjective = "Gebt die desynchronisierte Vibroklinge Sapphronetta Chaise im Rostbolzen.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[56074] = { id = 56074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenleitung" }
quests[56075] = { id = 56075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Kraft", description = "Diese Naga ziehen ihre Kraft aus der Leere.\n\nJede aufgezeichnete Schriftrolle bedeutet geteiltes Wissen, und dieses Wissen ist Macht.\n\nEs leuchtet wohl ein, dass wir, wenn wir ihnen ihr Wissen wegnehmen, auch ihre Macht stehlen.\n\nMeine Logik mag zwar lückenhaft sein, aber wir sollten es trotzdem versuchen!", sourceObjective = "Sammelt 8 Schriftrollen der Shirakess.", progress = "Habt Ihr alle Schriftrollen bekommen?", completion = "Nehmt ihnen ein wenig Magie, und sie werden ein wenig schwächer.\n\nWenn durch sonst nichts, werden wir diesen Krieg durch Zermürbung gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56076] = { id = 56076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssisches Ritual" }
quests[56078] = { id = 56078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen den Strom" }
quests[56080] = { id = 56080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Murlocs" }
quests[56081] = { id = 56081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okto-Griff" }
quests[56082] = { id = 56082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Bots", description = "Die Bots greifen uns an, seit wir hier gelandet sind. Wir müssen diesen Strand halten!\n\nMeine Expeditionswachen könnten Eure Hilfe brauchen, {name}. Geht ihnen zur Hand und zerstört Bots am Strand und in den Wäldern in der Nähe.", sourceObjective = "Vernichtet 15 angreifende Bots.", completion = "Sie greifen immer noch an, aber wir schaffen das jetzt allein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56083] = { id = 56083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Arbeitsbedingungen", description = "Diese randalierenden Bots lassen nicht locker!\n\nWir bezahlen den besten Goblins auf diesem Planeten ein Heidengold und ich will verdammt sein, wenn ich ein paar Maschinen mit durchgebrannten Sicherungen erlaube, sie von der Arbeit abzuhalten.\n\nGanz zu schweigen von der Schmiermaxengewerkschaft, die mir mit ihren \"lebensgefährlichen Arbeitsbedingungen\" in den Ohren liegen. Beschützt die Arbeiter!", sourceObjective = "Vernichtet 15 angreifende Bots.", completion = "Ihr habt gut gekämpft, wenn man bedenkt, dass Ihr ein {race} seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[56086] = { id = 56086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Holografisches Digitalisierungsrelais", description = "<Dies scheint der Bauplan für eine Art holografischen Teleporter zu sein.\n\nIhr müsstet den Bauplan im Rostbolzen in Pascal-K1N6s Datenbank hochladen können.>", sourceObjective = "Ladet den Bauplan in die Datenbank von Pascal-K1N6.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr einen neuen Bauplan gefunden, mein fleischiger Freund?\n\nIch werde ihn umgehend meiner Datenbank hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56087] = { id = 56087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Experimentelles Abenteureraccessoire", description = "<Dies scheint der Bauplan für eine Art Ring zu sein... oder vielleicht ein anderes Schmuckstück?\n\nIhr müsstet den Bauplan im Rostbolzen in Pascal-K1N6s Datenbank hochladen können.>", sourceObjective = "Ladet den Bauplan in die Datenbank von Pascal-K1N6.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr einen neuen Bauplan gefunden, mein fleischiger Freund?\n\nIch werde ihn umgehend meiner Datenbank hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56090] = { id = 56090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbräustellung" }
quests[56091] = { id = 56091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duftdrüse der Usurpatorin", description = "Wenn eine neue Königin geboren wird und alt genug ist, um ihren eigenen Schwarm zu gründen, verlässt sie den Stock. Ihr Geruch zieht einige Schwarmangehörige an, die dann mit ihr in ihre neue Heimat fliegen. Diese hier hat dank Euch wahrscheinlich nie die Chance dazu erhalten.\n\nDie Schwarmmutter wird sich für diesen Gegenstand interessieren.", sourceObjective = "Bringt die Duftdrüse der Usurpatorin zur Honigrückenschwarmmutter, um eine Belohnung zu erhalten.\n\nBereitgestellter Gegenstand:", completion = "<Die Schwarmmutter verschlingt eilends die Duftdrüse und zappelt dann vor Euch herum.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56092] = { id = 56092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geléevorrat des Schwarmdiebs", description = "Dieser Ettin war ein bekanntes und oft gefürchtetes Gesicht unter den Bienen des Honigrückenschwarms. Ihre Geléespeicher werden von seinem Ableben profitieren.\n\nDie Schwarmmutter wird sich für diesen Gegenstand interessieren.", sourceObjective = "Bringt den Geléevorrat des Schwarmdiebs zur Honigrückenschwarmmutter, um eine Belohnung zu erhalten.\n\nBereitgestellter Gegenstand:", completion = "<Die Schwarmmutter summt lebhaft.>\n\nBzzzt! Bzzzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56095] = { id = 56095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe von Nar'anan", description = "He, Ihr da, {race}. Könnt Ihr mir helfen?\n\nIch habe diese Pylonen hier gefunden. Es sieht danach aus, als ob sie Erinnerungen eines bedeutenden Hochgeborenen beinhalten, der hier vor langer Zeit gelebt hat.\n\nIch komme aber nicht näher an den Rest heran, weil diese Schnappdrachen den Weg versperren. Besonders diese Terrorschlünde...\n\nKönnt Ihr die Pylonen für mich aktivieren? Wir Tortollaner lieben alte Dinge und das hier ist eine potenzielle Goldmine!\n\nUnd schreibt bitte unbedingt alles auf, was Ihr seht!", sourceObjective = "Aktiviert die Erinnerungspylonen in Nar'anan und seht Euch die vergangenen Geschehnisse an.", completion = "Zeigt, was Ihr da habt!\n\n<Sammler Kojo liest Eure Notizen... langsam>\n\nIch glaube, wir haben soeben den Ursprung der Schnappdrachen gefunden! Mal sehen, was wir noch erfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[56097] = { id = 56097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzverkrustete Scheibe", description = "<Findet jemanden, der die Daten auf der schmutzverkrustete Scheibe wiederherstellen kann.>" }
quests[56098] = { id = 56098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwehr im Ableben", description = "<Nachdem Ihr nun etwas Erfahrung mit Zin'anthiden gesammelt habt, rupft Ihr eines ihrer Tentakel vom Hauptkörper. Dabei zieht sich das Tentakel zusammen und rollt sich auf, sodass Ihr nicht mehr an die Blüten an seiner Innenseite herankommt. Vielleicht weiß Ausbilder Ulooaka mehr über diese Pflanze und wie man ihre Abwehrreaktion umgeht.>", sourceObjective = "Fragt Ausbilder Ulooaka nach den Tentakeln der Zin'anthide.\n\nBereitgestellter Gegenstand:", completion = "Zin'anthiden sind keine bloßen Pflanzen, {name}. Wenn sie bemerken, dass sie von Räubern bedroht werden, verhalten sie sich wie alle anderen Lebewesen. Sogar nach ihrem Tod bleibt ihr Abwehrmechanismus intakt.\n\nUm ihr Erntepotenzial voll auszuschöpfen, müsst Ihr sie in falscher Sicherheit wiegen. Hier, ich zeige Euch eine Technik, die ich kenne.", sourceObjectiveStatus = "unverified-source-field" }
quests[56099] = { id = 56099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quell der Verderbnis" }
quests[56103] = { id = 56103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obacht mit dem Osmenit", description = "<Nachdem Ihr auf das Erz eingeschlagen habt, hebt Ihr ein paar Splitter auf, die auf den Boden gefallen sind. Es müsste doch einen Weg geben, mehr aus diesen Vorkommen herauszuholen, ohne so viel Ausschuss zu generieren. Vielleicht weiß Ausbilder Ulooaka, wie man das Erz besser abbauen kann.>", sourceObjective = "Fragt Ausbilder Ulooaka nach den Osmenitsplittern.\n\nBereitgestellter Gegenstand:", completion = "Ah, nun, das liegt an der zerbrechlichen Natur des Erzes. Ihr müsst Eure Technik ein wenig anpassen.\n\nVersucht es statt mit harten, schweren Schlägen lieber damit, es genau an der Kante zu treffen, wo das Erz auf den Fels trifft.\n\nÄhnlich, wie man eine Frucht schält. Ich zeige Euch, wie ich es meine...", sourceObjectiveStatus = "unverified-source-field" }
quests[56107] = { id = 56107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kind des Schwarms" }
quests[56108] = { id = 56108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Stock verlassen", description = "<Die riesige Biene lässt ihre Antennen in Eure Richtung zucken. Sie schwingt ihren Unterleib in Richtung des Höhleneingangs.>\n\nVielleicht weiß Ingmar, was hier vor sich geht.", sourceObjective = "Sprecht mit Ingmar in der Honigrückenbrutstätte.", completion = "<Sie zappelt eifrig in ihrem neuen Geschirr.>\n\nBzzzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56109] = { id = 56109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger des Schwarms" }
quests[56110] = { id = 56110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Verteidiger tritt hervor" }
quests[56111] = { id = 56111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Usurpation" }
quests[56112] = { id = 56112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein königliches Erwachen" }
quests[56116] = { id = 56116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer wieder Wiederverwertung", progress = "<WARNUNG 3.6.4 - Y: Alle Gliedmaßen von den Türen fernhalten, um irreversible Wiederverwertisierung selbiger zu vermeiden.>", completion = "Ihr habt das Bündel Teile in den Wiederverwertisierer DX-82 gegeben. Die Türen schließen sich und die Maschine nimmt mit einem anschwellenden, summenden Geräusch aus dem Inneren die Arbeit auf. Die Frequenz des Geräuschs wird immer höher und steigert sich zu einem hohen Sirren. Die heftig vibrierende Maschine scheint jeden Augenblick explodieren zu wollen..." }
quests[56117] = { id = 56117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertbare Teile", description = "<Dieses Bündel wiederverwertbarer Teile könnte wertvoll sein. Die Gnome in der Umgebung werfen ihren Schrott anscheinend in eine Art Vorrichtung in der Nähe.>", sourceObjective = "Sammelt 1 Bündel wiederverwertbarer Teile.", progress = "<WARNUNG 3.6.4 - Y: Alle Gliedmaßen von den Türen fernhalten, um irreversible Wiederverwertisierung selbiger zu vermeiden.>", completion = "Ihr habt das Bündel Teile in den Wiederverwertisierer DX-82 gegeben. Die Türen schließen sich und die Maschine nimmt mit einem anschwellenden, summenden Geräusch aus dem Inneren die Arbeit auf. Die Frequenz des Geräuschs wird immer höher und steigert sich zu einem hohen Sirren. Die heftig vibrierende Maschine scheint jeden Augenblick explodieren zu wollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[56118] = { id = 56118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappt zurück", description = "Ich muss Euch um einen Gefallen bitten.\n\nDie Schriftrollengelehrte Nola hat mir diese Schriftrolle gegeben, um mich bei meinen Abenteuern hier in Nazjatar zu beschützen! Sie ist eine gütige Seele, aber ihre Schriftrollen sind nicht immer unbedingt... zuverlässig.\n\nIhr seht aus wie <ein tapferer Abenteurer, der/eine tapfere Abenteurerin> die; schon einiges gesehen hat. Könntet Ihr die Schriftrolle für mich testen? Und wenn Ihr schon dabei seid, könnt Ihr auch gleich ein paar Bedrohungen beseitigen.", sourceObjective = "Wendet die Schriftrolle überbordender Macht auf die Terrorschlünde der Schnappdrachen an und tötet Schnappdrachen in Nar'anan.", completion = "Wow! So stark, was?\n\nDann werde ich sie von nun an immer mit mir führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[56119] = { id = 56119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ankoaner der Meeresklinge", description = "Unterstützt die Ankoaner in Nazjatar, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests in Nazjatar ab.", completion = "Möge Neptulon Euch in seinem Segen baden.", sourceObjectiveStatus = "unverified-source-field" }
quests[56120] = { id = 56120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entfesselten", description = "Unterstützt die Entfesselten in Nazjatar, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests in Nazjatar ab.", progress = "Kehrt zu mir zurück, wenn Eure Unterstützung abgeschlossen ist, {name}.", completion = "Ihr wart da draußen wirklich der entscheidende Unterschied!\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[56121] = { id = 56121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quirlige Quallen" }
quests[56126] = { id = 56126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staubtrockenes Problem", description = "<Während Ihr auf das Erz einschlagt, fällt Euch auf, dass viel davon zu Staub zerfällt und vor Euch zu Boden rieselt. Die zerfallene Menge ist so groß, dass man daraus etwas herstellen könnte, wenn sie nur ihre Form behielte.\n\nIhr solltet mit Ausbilder Ulooaka reden und nachfragen, ob man diesen Zerfall verhindern kann.>", sourceObjective = "Fragt Ausbilder Ulooaka nach dem Osmenitstaub.\n\nBereitgestellter Gegenstand:", completion = "Flöze, in denen sich Osmenit befindet, sind von anderer Struktur als die reinen Vorkommen.\n\nWenn Ihr das gesamte Osmenit eines Flözes erhalten wollt, müsst Ihr das Erz in Ruhe lassen und Euch um den Fels drum herum kümmern.\n\nDas widerspricht eigentlich der normalen Herangehensweise beim Abbauen, aber vertraut mir, das Ergebnis wird Euch überzeugen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56128] = { id = 56128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde ertränken", description = "Wir müssen jetzt zuschlagen, bevor die Horde eine Chance hat, eine Stellung zu sichern. Greift ihre Champions an und schlagt sie zurück.", sourceObjective = "Tötet 25 Spielercharaktere der Horde in Nazjatar bei aktivem Kriegsmodus.", completion = "Wenn wir den Druck aufrechterhalten, wird die Horde niemals Erfolg haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[56129] = { id = 56129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Die Schlacht um Stromgarde" }
quests[56131] = { id = 56131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Viele gefährliche Kreaturen und die Verbündeten meines Vaters werden versuchen, uns zu vernichten.\n\nHelft uns beim Sichern dieser Insel und tötet fünf unserer mächtigsten Feinde.", sourceObjective = "Tötet seltene Gegner auf der Insel Mechagon.", sourceObjectiveStatus = "unverified-source-field" }
quests[56136] = { id = 56136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Kriegsfront: Die Schlacht um Stromgarde", description = "Wenn die Horde denkt, sie kann Burg Stromgarde stürmen, täuscht sie sich gewaltig. Arathi wird nicht fallen! Das lassen wir nicht zu!\n\nMacht Euch bereit für die Schlacht.", sourceObjective = "Besiegt die Horde in der Schlacht um Stromgarde.", completion = "Gut gekämpft, {name}, obwohl ich glaube, dass es töricht wäre, jetzt schon unsere Deckung fallen zu lassen. Unser Feind wird nicht einfach untätig dasitzen, während wir Burg Stromgarde wieder aufbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56137] = { id = 56137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Kriegsfront: Die Schlacht um Stromgarde", description = "Unser Feind lässt nichts unversucht, um Arathi für sich zu beanspruchen. Wir können nicht erlauben, dass es in seine Hände fällt! Wir müssen ihn aufhalten, bevor die Burg wieder steht!\n\nZu den Waffen! Die Allianz naht.", sourceObjective = "Besiegt die Allianz in der Schlacht um Stromgarde.", completion = "Ein sehr guter Kampf, {name}. Ein weiteres Mal habt Ihr Euch als furchtloser Krieger der Horde bewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56139] = { id = 56139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrottschätze", description = "Jeder hier muss hart arbeiten, um Ressourcen für unser Vorhaben heranzuschaffen.\n\nFindet zehn mechanisierte Truhen auf der Insel und öffnet sie." }
quests[56141] = { id = 56141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Viele gefährliche Kreaturen und die Verbündeten meines Vaters werden versuchen, uns zu vernichten.\n\nHelft uns beim Sichern dieser Insel und tötet fünf unserer mächtigsten Feinde.", sourceObjective = "Tötet seltene Gegner auf der Insel Mechagon.", sourceObjectiveStatus = "unverified-source-field" }
quests[56142] = { id = 56142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anpassen, verbessern, überwinden!", description = "Izira Getriebeschwur ist immer noch am Leben. Sie ist stärker als alle anderen Kämpfer des Rostbolzens, aber ihre Beine sind defekt. Wenn wir überleben wollen, müssen wir Teile finden, um sie wieder auf Vordermann zu bringen.\n\nHier gibt es überall Maschinen, die wir ausschlachten können. Wenn wir beharrlich bleiben, sollten wir Iziras Beine reparieren können.\n\nHelft mir, diese Teile zu finden.", sourceObjective = "Besorgt 20 Handvoll makellose Hundebolzen, 4 winzige Beinstreben und 2 Wachpostenfußmuttern.", progress = "Wir müssen anfangen zu suchen!", completion = "Die sind in hervorragendem Zustand!", sourceObjectiveStatus = "unverified-source-field" }
quests[56143] = { id = 56143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Professorin Elryna", description = "Es sieht so aus, als könnte Elrynas Geschichte ein interessantes Ende finden. Dieser Pylon hier verhält sich merkwürdig. Ich glaube, ich weiß auch warum!\n\nDiese Dinger verwenden Erinnerungskerne. Kleine Kristalle, die sich im Zentrum der Kugel befinden. Ich wette, dass wir in dem alten Magierturm einen finden.\n\nDort gibt es einen Schnappdrachen, der größer als die anderen Terrorschlunde ist, also behaltet die Schriftrolle fürs Erste. Sie hilft Euch sicher bei Eurem Kampf. Das Biest ist riesig!", sourceObjective = "Besiegt die Schnappdrachenmatriarchin, sammelt den Erinnerungskern ein, aktiviert den Erinnerungspylonen und seht Euch das Schicksal von Professorin Elryna an.", progress = "Was ist an jenem schicksalhaften Tag geschehen?", completion = "Aha. Sie wurde also von diesem General hintergangen?\n\nEr hat wahrscheinlich den ganzen Ruhm für sich eingeheimst.\n\nZu schade. Aber immerhin kennen wir jetzt die Wahrheit! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56144] = { id = 56144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tatze der alten Nasha", description = "Die Tatze der alten Bärin ist klebrig vom Honig. Wahrscheinlich hat sie einige Stöcke geplündert, bevor Ihr sie aufgehalten habt.\n\nDie Schwarmmutter wird sich für diesen Gegenstand interessieren.", sourceObjective = "Bringt die Tatze der alten Nasha zur Honigrückenschwarmmutter, um eine Belohnung zu erhalten.\n\nBereitgestellter Gegenstand:", completion = "<Die Schwarmmutter summt zufrieden.>\n\nBzzzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56145] = { id = 56145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Verbessertes Abenteureraccessoire", description = "<Dieser Bauplan beschreibt, wie man noch mehr Macht in einen Ring oder ein Schmuckstück komprimieren kann!\n\nIhr müsstet den Bauplan im Rostbolzen in Pascal-K1N6s Datenbank hochladen können.>", sourceObjective = "Ladet den Bauplan in die Datenbank von Pascal-K1N6.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr einen neuen Bauplan gefunden, mein fleischiger Freund?\n\nIch werde ihn umgehend meiner Datenbank hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56146] = { id = 56146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kelpbeerenwein keltern", description = "<Dies ist ein leeres Kelpbeerensaftfass.\n\nJemand ist in der Nähe, der sich über eine Wiederauffüllung freuen würde.>", sourceObjective = "Bringt Kelpbeerenwein zu Maedin in Maedins Herausforderung.", progress = "Habt Ihr mir etwas mitgebracht?", completion = "Oh, Ihr wisst genau, was dieses alte Mädchen mag!", sourceObjectiveStatus = "unverified-source-field" }
quests[56148] = { id = 56148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Nazjatar", description = "Unsre Ziele in Nazjatar werd'n durch das Auftauch'n von Allianzabschaum blockiert.\n\nTötet so viele von denen, wie Ihr dort finden könnt, und meldet Euch dann wieder bei mir.", sourceObjective = "Tötet Mitglieder der Allianz in Nazjatar.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56149] = { id = 56149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speisung der Vielen", description = "Ich danke Euch für die Hilfe, die Eure Allianz meinem Volk hat angedeihen lassen, aber wir haben kaum noch Essen und Vorräte.\n\nWenn wir nicht genug Vorräte für die Allianz und meinen Klan auftreiben können, werden wir innerhalb einer Woche keine Nahrung mehr haben.\n\nGlücklicherweise gibt es in diesem Gebiet unglaublich viele Tiefenrochen. Allerdings werden wir bei ihrer Jagd Hilfe benötigen, um genug Vorräte für unser Lager zusammenzubekommen.\n\nNehmt diesen Tiefenhaken und zieht die Tiefenrochen aus dem Himmel.", sourceObjective = "Sammelt 10 Stücke Tiefenrochenfleisch.", progress = "Seid Ihr von der Jagd zurückgekehrt?", completion = "Ihr habt einen schönen Batzen Tiefenrochenfleisch mitgebracht. Ich werde dafür sorgen, dass alles ins Lager geschafft wird. Danke für Euren Einsatz, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56150] = { id = 56150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kritch töten", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr.\n\n<Rlgmrr hüpft verängstigt herum und zeigt auf die Höhle.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<Er macht ein beängstigendes Gesicht und Schnappbewegungen mit seinen Händen.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", sourceObjective = "Tötet den Kritch.", completion = "Llrmmrgl! Mrgggl mrgl!\n\n<Rlgmrr lacht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56151] = { id = 56151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poens Leibgericht", description = "Poen hilft uns immer, wenn wir uns um Gerettete kümmern.\n\nKönnt Ihr ein wenig Fleisch von den Aalen im Süden sammeln?\n\nIch mache ihm als Dank hin und wieder gerne sein Leibgericht.\n\nDas Gericht hat zudem eine starke Regenerationskraft und hilft den Geretteten. \n\nDas ist die Macht der Köstlichkeit, glaubt mir!", sourceObjective = "Sammelt 15 Stücke frisches Unagi.", progress = "Habt Ihr genug Fleisch gesammelt?", completion = "Das ist wirklich ein Leckerbissen für uns alle.\n\nIch danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[56152] = { id = 56152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Schuppe gespuckt", description = "Ich brauche Eure Hilfe, {class}. Ich habe die Hydras in der Nähe wegen ihrer Schuppen gejagt, aber meine Waffe ist im Kampf zerbrochen.\n\nAus Hydraschuppen kann man wunderbar stabile und belastbare Rüstungen für unsere Krieger herstellen. Unser Klan braucht diese Schuppen, um Rüstungen zu fertigen und zu reparieren.\n\nWenn wir nicht bald Nachschub bekommen, haben wir nicht genug, um uns für den Kampf gegen die Naga zu rüsten.", sourceObjective = "Sammelt 20 Hydraschuppen.", progress = "Habt Ihr die Jagd beendet?", completion = "Ich danke Euch, {class}. Diese Schuppen helfen uns wirklich sehr in unserem Kampf gegen die Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[56153] = { id = 56153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheldelikatesse", description = "Neptulische Muscheln sind wichtig für die Ernährung der Ankoaner.\n\nViele Leute vergessen, wie wichtig die richtige Ernährung in Zeiten des Krieges ist. Eine Kriegerin kann die tödlichsten Waffen und das beste Training haben, aber wenn sie nicht die richtige Verpflegung hat, wird sie niemals ihre maximale Kraft entfalten.\n\nJetzt, wo Mezzameer Eure Allianz beherbergt, müssen wir hart dafür arbeiten, genug Nahrung für unsere Soldaten heranzuschaffen.\n\nSammelt so viele neptulische Muscheln, wie Ihr finden könnt, und ich kümmere mich darum, dass sie sicher in unserem Lager ankommen.", sourceObjective = "Sammelt 10 neptulische Muscheln.", progress = "Habt Ihr die neptulischen Muscheln besorgt?", completion = "Die sind genau richtig.\n\nVielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56154] = { id = 56154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sie sich verstecken", description = "Die Naga schicken Assassinen, um unsere Streitkräfte zu schwächen.\n\nSie verstecken sich in der Nähe und töten alle, die sie nicht in ihre Sklavenpferche entführen können.\n\nNehmt diesen speziellen Meerschwamm mit. Seine Sporen enthüllen die Naga in ihrer ganzen Heimtücke.\n\nSobald sie sichtbar sind, müsst Ihr sie töten, bevor sie fliehen und Verstärkung holen können.\n\nAzshara wird fallen!", sourceObjective = "Benutzt den frischen Schwamm, um 5 Assassinen der Zanj'ir aufzuspüren und zu töten.", completion = "Gut gemacht, {class}. Jetzt ist die Straße wieder sicherer für Reisende.", sourceObjectiveStatus = "unverified-source-field" }
quests[56155] = { id = 56155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Die Geysire sind sehr instabil und können jeden Moment ausbrechen.\n\nIch befürchte, dass Azsharas Missbrauch des Gezeitensteins den Elementen in Nazjatar irreparable Schäden zufügt.\n\nWir müssen tun, was wir können, um weitere Zerstörungen zu verhindern.\n\nBenutzt dieses Dichtungsmittel, um die nächsten Eruptionen zu unterdrücken. Währenddessen werde ich tun, was in meiner Macht steht, um die Elemente zu stabilisieren.", sourceObjective = "Versiegelt 5 instabile Geysire und tötet das gestörte Algan.", completion = "Gute Arbeit, {name}. Dank Eurer Hilfe beim Versiegeln der Geysire konnte ich die Elemente stabilisieren und den Druck an einen sicheren Ort lenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[56156] = { id = 56156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gehärtete Klinge", description = "Die Klingen, die ich trage, sind neu gefertigt. Es ist Zeit, sie im Blut meiner Feinde zu härten.\n\nMir wurde berichtet, dass Ihr äußerst schlachterprobt seid. Auch ich beherrsche die Kunst des Kampfes und es wäre mir eine Ehre, an Eurer Seite zu kämpfen.\n\nBegleitet mich, {class}, und wir werden zusammen das Blut unserer Feinde vergießen.", sourceObjective = "Tötet 15 Naga mit Klingenkämpfer Inowari.", completion = "Es war mir eine große Ehre, an Eurer Seite kämpfen zu dürfen, {name}. Wenn Ihr mich in Zukunft brauchen solltet, müsst Ihr mich nur fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56157] = { id = 56157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Es gibt einige Geysire in der Nähe, die bald ausbrechen werden.\n\nLeider sind die Elemente in diesem Gebiet nicht stabil genug, um die Kräfte eines Ausbruchs auszuhalten.\n\nIch brauche jemanden, der die Geysire verstopft, während ich die Elemente dazu nutze, den Druck in eine sichere Region in Nazjatar umzuleiten.\n\nBenutzt dieses Dichtungsmittel und verstopft die Geysire. Ich arbeite derweil an der Wiederherstellung des Gleichgewichts der Elemente.", sourceObjective = "Versiegelt 5 instabile Geysire und tötet das gestörte Algan.", completion = "Gute Arbeit, {name}. Dank Eurer Hilfe beim Versiegeln der Geysire konnte ich die Elemente stabilisieren und den Druck an einen sicheren Ort lenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[56158] = { id = 56158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Die Elemente werden wegen Azsharas Missbrauchs des Gezeitensteins zunehmend instabiler.\n\nDie Geysire in der Nähe könnten jeden Moment ausbrechen. Jeder Ausbruch gefährdet das zerbrechliche Gleichgewicht des Lebens auf der Oberfläche.\n\nBenutzt dieses Dichtungsmittel und verstopft die Geysire. Ich arbeite derweil an der Wiederherstellung des Gleichgewichts der Elemente und versuche, den explosiven Druck aus dem Untergrund in ein sicheres Gebiet umzuleiten.", sourceObjective = "Versiegelt 7 instabile Geysire.", completion = "Gute Arbeit, {name}. Dank Eurer Hilfe beim Versiegeln der Geysire konnte ich die Elemente stabilisieren und den Druck an einen sicheren Ort lenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[56159] = { id = 56159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Die Geysire sind sehr instabil und können jeden Moment ausbrechen.\n\nIch befürchte, dass Azsharas Missbrauch des Gezeitensteins den Elementen in Nazjatar irreparable Schäden zufügt.\n\nWir müssen tun, was wir können, um weitere Zerstörungen zu verhindern.\n\nBenutzt dieses Dichtungsmittel, um die nächsten Eruptionen zu unterdrücken. Währenddessen werde ich tun, was in meiner Macht steht, um die Elemente zu stabilisieren.", sourceObjective = "Versiegelt 7 instabile Geysire.", completion = "Gute Arbeit, {name}. Dank Eurer Hilfe beim Versiegeln der Geysire konnte ich die Elemente stabilisieren und den Druck an einen sicheren Ort lenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[56160] = { id = 56160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Es gibt einige Geysire in der Nähe, die bald ausbrechen werden.\n\nLeider sind die Elemente in diesem Gebiet nicht stabil genug, um die Kräfte eines Ausbruchs auszuhalten.\n\nIch brauche jemanden, der die Geysire verstopft, während ich die Elemente dazu nutze, den Druck in eine sichere Region in Nazjatar umzuleiten.\n\nBenutzt dieses Dichtungsmittel und verstopft die Geysire. Ich arbeite derweil an der Wiederherstellung des Gleichgewichts der Elemente.", sourceObjective = "Versiegelt 6 instabile Geysire.", completion = "Gute Arbeit, {name}. Dank Eurer Hilfe beim Versiegeln der Geysire konnte ich die Elemente stabilisieren und den Druck an einen sicheren Ort lenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[56161] = { id = 56161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Meer", description = "Jetzt, da hier wieder alles unter Kontrolle ist, bin ich sicher, dass sie in Nazjatar Eure Hilfe gut brauchen können!\n\nWarum geht Ihr nicht zurück auf See... ähm, ich meine unter See und trefft Euch mit unseren neuen Freunden dort?", sourceObjective = "Kehrt nach Neuheim in Nazjatar zurück.", completion = "Willkommen zurück. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[56162] = { id = 56162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Meer", description = "Jetzt, da hier wieder alles unter Kontrolle ist, bin ich sicher, dass sie in Nazjatar Eure Hilfe gut brauchen können!\n\nWarum geht Ihr nicht zurück auf See... ähm, ich meine unter See und trefft Euch mit unseren neuen Freunden dort?", sourceObjective = "Kehrt nach Mezzameer in Nazjatar zurück.", completion = "Danke, dass Ihr uns wieder zu Hilfe kommt. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[56163] = { id = 56163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebundener Elementar" }
quests[56165] = { id = 56165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Außerordentliches Abenteureraccessoire", description = "<Dieser Bauplan beschreibt, wie man außerordentlich viel Macht in einen Ring oder ein Schmuckstück komprimieren kann!\n\nIhr müsstet den Bauplan im Rostbolzen in Pascal-K1N6s Datenbank hochladen können.>", sourceObjective = "Ladet den Bauplan in die Datenbank von Pascal-K1N6.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr einen neuen Bauplan gefunden, mein fleischiger Freund?\n\nIch werde ihn umgehend meiner Datenbank hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56166] = { id = 56166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder braucht etwas", description = "Es gibt sicher noch andere im Lager, die Hilfe brauchen. Fragt herum und seht, wo Ihr helfen könnt.\n\nErstattet Sprecher Utia aber auf jeden Fall Bericht darüber.", sourceObjective = "Sprecht mit Einwohnern von Mezzameer und helft ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56167] = { id = 56167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochlanduntersuchung", description = "Als ich diese Essenzen das erste Mal gespürt habe, war mir nicht bewusst, was für eine bedeutende Rolle sie spielen würden. Jetzt ist es nur noch eine Frage der Zeit, bis alle Schwärme beteiligt sind.\n\nIch habe bereits mit den anderen Aspekten Kontakt aufgenommen, doch von Alexstrasza habe ich noch nichts gehört. Es ist merkwürdig, dass sie sich so ruhig verhält, wenn solche Mächte sich formieren.\n\nSie wurde zuletzt im Zinnoberrefugium im Schattenhochland gesichtet.\n\nIch befürchte, sie könnte in Gefahr sein. Beeilen wir uns.", sourceObjective = "Trefft Kalecgos im Schattenhochland.", completion = "Es ist viel schlimmer, als ich gedacht hätte. Wir haben versucht, das Refugium zu erreichen, aber wir sind nicht einmal bis zum Kamm gekommen.\n\nIrgendetwas beobachtet den Himmel und verhindert, dass wir Alexstrasza erreichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[56168] = { id = 56168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabriküberholt", description = "Ihr müsst uns einen wiederverwerteten Kriecherverteiler besorgen.\n\nIm Schrottwattdepot solltet Ihr fündig werden, wenn Ihr Teile, die Ihr dort findet, wiederverwertet.", sourceObjective = "Besorgt einen wiederverwerteten Kriecherverteiler.", progress = "Macht Euch auf den Weg zum Schrottwattdepot und legt los!", completion = "Gute Arbeit. Das ist genau das, was ich brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[56172] = { id = 56172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andere Interessen", description = "Madame Goya interessiert sich für viele ungewöhnliche Gegenstände und nicht nur seltene Metalle.\n\nHaltet auf Euren Reisen in Nazjatar Ausschau nach diesen speziellen Gegenständen.\n\nBringt sie mir, dann wird Madame Goya in Betracht ziehen, Euch speziellen Zugang zu gewähren.", sourceObjective = "Bringt 5 seltsame Murlochörner zum Stahlweisen Gao.", progress = "Habt Ihr die Gegenstände gefunden?", completion = "Ausgezeichnete Arbeit. Wir werden uns wieder sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56173] = { id = 56173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andere Interessen", description = "Madame Goya interessiert sich für viele ungewöhnliche Gegenstände und nicht nur seltene Metalle.\n\nHaltet auf Euren Reisen in Nazjatar Ausschau nach diesen speziellen Gegenständen.\n\nBringt sie mir, dann wird Madame Goya in Betracht ziehen, Euch speziellen Zugang zu gewähren.", sourceObjective = "Bringt 5 unidentifizierbare Massen zum Stahlweisen Gao.", progress = "Habt Ihr die Gegenstände gefunden?", completion = "Ausgezeichnete Arbeit. Wir werden uns wieder sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56174] = { id = 56174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andere Interessen", description = "Madame Goya interessiert sich für viele ungewöhnliche Gegenstände und nicht nur seltene Metalle.\n\nHaltet auf Euren Reisen in Nazjatar Ausschau nach diesen speziellen Gegenständen.\n\nBringt sie mir, dann wird Madame Goya in Betracht ziehen, Euch speziellen Zugang zu gewähren.", sourceObjective = "Bringt 5 zerfallende Sandskulpturen zum Stahlweisen Gao.", progress = "Habt Ihr die Gegenstände gefunden?", completion = "Ausgezeichnete Arbeit. Wir werden uns wieder sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56175] = { id = 56175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissionsfrei", description = "Wir brauchen ein paar leere Energiezellen für den Batteriepack am Steuerungsmodul des Reittiers.\n\nSchaut, ob Ihr sie für mich auftreiben könnt.", sourceObjective = "Sammelt 20 leere Energiezellen.", progress = "Wir müssen diesen Batteriepack reparieren.", completion = "Gute Arbeit. Das wird wirklich helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56177] = { id = 56177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenleitung" }
quests[56178] = { id = 56178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenleitung" }
quests[56180] = { id = 56180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebundener Elementar" }
quests[56181] = { id = 56181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geht auf mich", description = "Ihr stimmt mir doch sicher zu, dass Pascal-K1N6 die genialste Erfindung ist, die Ihr je gesehen habt!\n\nWenn Ihr noch nicht überzeugt seid, dann versucht doch mal, ihn an seine Grenzen zu bringen. Nur zu!\n\nBringt ihm mehr Rohstoffe und Baupläne und er wird Euch alles bauen, was Ihr braucht!", completion = "Ihr habt in der Stadt viel gute Arbeit geleistet, {name}. Ihr seid eine wahre Bereicherung für den Widerstand.\n\nIch habe auch gesehen, wie Ihr meinen Schweißbrenner bewundert... Ein geniale Erfindung, nicht wahr?\n\nHört mal, ich werde den Bauplan für den Schweißbrenner des Schrottmeisters bei Pascal-K1N6 für Euch freischalten.\n\nIhr müsst mir nicht danken. Eure gute Arbeit soll schließlich belohnt werden." }
quests[56184] = { id = 56184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piraten, Seeungeheuer, Roboter", description = "Ich habe ihn endlich gefunden! Das ist die letzte Ruhestätte meines Vaters, nachdem seine Mannschaft gemeutert und ihn hier zum Sterben zurückgelassen hat.\n\nIch habe die Insel ausgespäht und drei Kisten gefunden, die Erinnerungsstücke meines Vaters enthalten.\n\nTut es bitte für mich und meine Familie. Holt mir das Schwert, die Kleidung und die Knochen meines Vaters aus den drei markierten Kisten zurück.", sourceObjective = "Findet Schwert, Kleidung und Knochen von DeMezas Vater.", progress = "Helft mir, die Überreste meines Vaters zu bergen.", completion = "Ich kann Euch nicht genug danken, also werde ich das auch nicht tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[56185] = { id = 56185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflüster von N'Zoth", description = "Fragt Ihr Euch, warum ich hier in der Herzkammer bin?\n\nNatürlich kam ich freiwillig her, aber eine Zeit lang gab es eine große Suche nach mir.\n\nKalecgos weiß noch, wie das lief. Sprecht mit ihm, wenn Ihr selbst erleben möchtet, wie ich sowohl dem Sprecher als auch dem Alten Gott immer einen Schritt voraus war.", sourceObjective = "Sprecht mit Kalecgos in der Herzkammer.", completion = "Ich wusste, dass N'Zoth mächtig ist, doch Ebenhorn in der Sicherheit der Kammer zu erwischen...\n\nWir müssen etwas dagegen unternehmen. Keiner von uns ist sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[56186] = { id = 56186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überall Spione", sourceObjective = "Sucht Furorion in der Taverne im Nebel.", progress = "Der Schwarze Prinz ist nicht hier. Aber wir könnten vielleicht helfen, ihn zu finden.", completion = "Gute Arbeit mit diesen Spionen.\n\nEs war lange Zeit ziemlich ruhig hier. Und auf einmal sind alle Augen auf uns gerichtet. Im wahrsten Sinne des Wortes.\n\nDer Schwarze Prinz ist bekannt dafür, seine wahren Absichten stets im Dunkeln zu halten. Ich lese eigentlich nicht die Tagebücher von anderen Leuten, aber er wusste wahrscheinlich, dass Ihr anders darüber denkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56187] = { id = 56187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pechschwingenschatten", description = "Offensichtlich ist der Schwarze Prinz nicht hier. Glaubt mir ruhig, wenn ich Euch sage, dass er nicht so einfach zu finden ist.\n\nIch würde an Eurer Stelle zum Schwarzfels aufbrechen. An der Stelle, wo Nefarian einst seinen Unterschlupf hatte, ist dort eine Art Terrasse in den Hang gemeißelt.\n\nFurorion hat diesen Ort seit langer Zeit beobachtet. Auch wenn er sich nicht selbst dort aufhält, trefft Ihr vielleicht jemanden, der weiß, wo Ihr suchen müsst.\n\nUnd {class}... Es ist offensichtlich, dass nicht nur Ihr nach ihm sucht. Passt auf Euch auf.", sourceObjective = "Sucht Furorion am Eingang zum Pechschwingenabstieg.", progress = "Mir schwirrt immer noch der Kopf... Sie haben mir so furchtbare... verlockende Dinge gezeigt...", completion = "Habt Dank. Sie... sind in meinen Kopf eingedrungen. Ich konnte sie nicht davon abhalten, zu finden, was sie suchten.\n\nDer Schwarze Prinz wollte, dass Ihr diese Seiten erhaltet. Er war sich sicher, dass das darin enthaltene Wissen Euch noch nützlich sein würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[56188] = { id = 56188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Katakomben!", description = "Ich habe durchgehalten, solange es ging, aber... die flüsternden Stimmen waren zu mächtig.\n\nIhr müsst Euch schnellstmöglich nach Karazhan begeben. Der Schwarze Prinz sagte, er wolle die Artefakte studieren, die dort in den Katakomben aufbewahrt sind.\n\nBitte, lasst nicht zu, dass mein Versagen seinen Untergang bedeutet!", sourceObjective = "Sucht Furorion vor den Katakomben von Karazhan.", progress = "<Scheinbar hat der Späher sein Leben für den Schwarzen Prinzen geopfert.>", completion = "<Der Späher hat sich heftig gewehrt, bevor er starb.\n\nIhr habt weitere Seiten aus Furorions Tagebuch bei seiner Leiche gefunden. Vielleicht ist der Schwarze Prinz selbst ganz in der Nähe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56189] = { id = 56189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Schwarzen Prinzen auf der Spur", description = "<Wie es aussieht, hat hier ein Kampf stattgefunden. N'Zoths Agenten sind wohl bereits in die Katakomben unter Karazhan eingedrungen.\n\nDer tote Späher hatte einen Satz Schlüssel dabei. Vielleicht gewähren sie Euch Zugang.\n\nMit etwas Glück könnt Ihr Furorion vor N'Zoths Agenten finden und etwas in Euren Besitz bringen, das Ebenhorn helfen könnte.>", sourceObjective = "Betretet die Katakomben von Karazhan und sucht nach einem Heilmittel für Ebenhorn.", progress = "<Der Zettel wurde anscheinend in aller Eile zurückgelassen und absichtlich so platziert, dass Ihr ihn findet.>", completion = "Auf dem Zettel steht:\n\n\"{name}. Wenn Ihr dies lest, dann ist Ebyssian dem Flüstern der Alten Götter erlegen. Zum Glück habe ich eine Methode vorbereitet, um ihn zu retten.\n\nNeben diesem Zettel findet Ihr einen Trank mit den von Euch gesuchten Eigenschaften. Bringt ihn meinem Bruder. Er wird ihm helfen, seinen Geist aus N'Zoths Umklammerung zu befreien.\n\nIch werde Euch schon bald persönlich für Eure Hilfe danken.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[56190] = { id = 56190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Ebenhorn", description = "<Der Trank wirkt mächtig und chaotisch. Er verändert scheinbar zufällig seine Farbe.\n\nDas muss das Gebräu sein, über das Furorion geschrieben hat. Es genügt, nur in seiner Nähe zu stehen, und Ihr bekommt einen klareren Kopf.\n\nIhr habt zwar nicht den Schwarzen Prinzen selbst gefunden, aber vielleicht hilft das, was er Euch hinterlassen hat, Ebenhorn.>", sourceObjective = "Kehrt zur Herzkammer zurück und behandelt Ebenhorn mit dem Trank der geistigen Klarheit.", completion = "Mein Verstand gehört endlich wieder mir. Woraus auch immer Furorion auch diesen Trank gebraut hat, es hat das Flüstern verstummen lassen.\n\nAber ich gehe davon aus, dass Ihr den Schwarzen Prinzen selbst nicht gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56205] = { id = 56205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ptraut mir einfach", description = "Ahhh, es tut gut, Euch zu sehen, {name}.\n\nWie geht es dem Unvollkommenen? Ist er immer noch gerne bei Euch?\n\nIch habe darüber nachgedacht. Vielleicht hält die Angst Euren nicht so ganz kleinen Freund noch zurück. Aber Eure Liebe ermöglicht es ihm, ohne Flügel zu wachsen und gedeihen. Vielleicht bringt ihn diese Liebe zurück in die luftigen Höhen.\n\nIhr müsst mir vertrauen. Ich möchte etwas versuchen.\n\nWenn ich mich nicht irre, seid Ihr beiden schon bald in der Luft, wie es eigentlich von der Natur vorgesehen ist!", sourceObjective = "Vertraut auf Pa'ku and Kua'fon.", completion = "Was habe ich Euch gesagt?\n\nEs hat nur die richtige Motivation gefehlt. Haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[56206] = { id = 56206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Die Schlacht um Stromgarde" }
quests[56209] = { id = 56209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen des Ursprungs", description = "Sieht ganz so aus, als hätte eine Gruppe Tol'vir, die sich als die Amathet bezeichnen, die Hallen des Ursprungs besetzt. Ich weiß nicht viel über sie. Nur, dass sie hier neu und nicht gerade die freundlichsten Zeitgenossen sind.\n\nWir müssen dort hinein, um die Schmiede zu reaktivieren. Sonst war es das für Azeroth!", sourceObjective = "Besiegt die Streitkräfte der Amathet und reaktiviert die Schmiede in den Hallen des Ursprungs.", progress = "Wenn wir dieses Ding nicht wieder aktiviert kriegen, ist Azeroth erledigt!", completion = "Wir haben die Schmiede zurück. Doch N'Zoth konnte bereits ihre Systeme beschädigen.\n\nEs steht uns wohl noch einiges an Arbeit bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[56210] = { id = 56210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sehersteine", description = "Ich habe ein Geschenk für Euch, {name}.\n\nSo einen Stein habt Ihr bestimmt noch nie gesehen. Für die Unwissenden ist das einfach nur ein simpler Stein, aber er ist weit mehr als das.\n\nDas ist ein Seherstein. Er zeigt Objekte, die durch Magie verborgen sind. Wenn Ihr nahe an einer Anomalie seid, beginnen die eingravierten Runen darauf zu glühen. \n\nVerwendet den Stein bei der Suche nach Schätzen, die durch uralte Magie verborgen wurden.", sourceObjective = "Findet Schätze in Nazjatar, die durch Magie verborgen wurden.", completion = "Seht Ihr, ich habe nicht gelogen. Diese Sehersteine sind unglaublich!", sourceObjectiveStatus = "unverified-source-field" }
quests[56211] = { id = 56211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sehersteine", description = "Ich habe ein Geschenk für Euch, {name}.\n\nSo einen Stein habt Ihr bestimmt noch nie gesehen. Für die Unwissenden ist das einfach nur ein simpler Stein, aber er ist weit mehr als das.\n\nDas ist ein Seherstein. Er zeigt Objekte, die durch Magie verborgen sind. Wenn Ihr nahe an einer Anomalie seid, beginnen die eingravierten Runen darauf zu glühen.\n\nVerwendet den Stein bei der Suche nach Schätzen, die durch uralte Magie verborgen wurden.", sourceObjective = "Findet Schätze in Nazjatar, die durch Magie verborgen wurden.", completion = "Jetzt wisst Ihr, dass diese Sehersteine wirklich unglaublich sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[56214] = { id = 56214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braves Mädchen", description = "Ich habe an Eurer Seite so viel gelernt. Ich kann kaum fassen, wie viele Naga wir getötet haben!\n\nAls Ihr ankamt, war ich erst skeptisch, ob Ihr wirklich einen Unterschied machen würdet. Wir kämpfen hier unten schon so lange, dass ich beinahe alle Hoffnung verloren hatte.\n\nJetzt endlich sehen wir aber einen Weg aus der Finsternis der Tiefe!\n\nIch habe einen Schnappdrachenwelpen aufgenommen, als wir Neuheim gegründet haben, und ich versuche seitdem, sie abzurichten. Ich glaube... ich hätte gerne, dass Ihr sie nehmt.\n\nEines Tages wird aus ihr ein großartiges Reittier werden... und eine treue Freundin.", sourceObjective = "Nehmt ein Geschenk von Eurem Begleiter an.", completion = "Kümmert Euch gut um sie, ja? Sie bedeutet mir sehr viel. \n\nAm liebsten frisst sie Tiefenrocheneier, vergesst das nicht.\n\nLebe wohl, Kleine! Neri liebt dich!", sourceObjectiveStatus = "unverified-source-field" }
quests[56215] = { id = 56215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerschale", description = "Hallo <mein Freund/meine Liebe>, ich wollte Euch nur sagen, dass die Reisen mit Euch das Beste waren, was ich bisher erlebt habe!\n\nIch hätte niemals gedacht, dass ich so viel über das Kämpfen lernen kann, aber jetzt fühle ich mich tatsächlich so, als ob ich mich selbst verteidigen könnte.\n\nIch werde all die Schwachen beschützen, die sich nicht selbst verteidigen können!\n\n<Poen holt eine Krabbe von irgendwo her. Sie hat einen hellen Panzer.>\n\nWie diesen kleine Kameraden hier. Ich habe ihn vor einer Weile gefunden, als wir draußen waren. Er sah so ängstlich aus.\n\nHey, warum nehmt Ihr die Krabbe nicht einfach?", sourceObjective = "Nehmt ein Geschenk von Eurem Begleiter an.", completion = "Ich habe noch nie eine Krabbe mit so einem farbig schimmernden Panzer gesehen. Das macht sie doch zu einer Zielscheibe.\n\nOhne Euch wären wir beide vielleicht verloren gewesen.\n\nHier, nehmt sie. Nur dank Euch sind wir hier alle jetzt viel sicherer.\n\nIch muss noch weitere Freunde beschützen!", sourceObjectiveStatus = "unverified-source-field" }
quests[56216] = { id = 56216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letztes Erbstück", description = "Wir sind gemeinsam vielen Gegnern gegenübergetreten und haben immer den Sieg davongetragen. Ich muss Euch heute für unsere Sicherheit danken und für meine neuen Kampffertigkeiten.\n\nIch will ehrlich mit Euch sein, <mein Freund/meine Liebe>. Ich hätte nicht gedacht, dass ich so lange lebe.\n\nMein Volk hatte einst Familien und Traditionen. Wir haben Symbole in unsere Talismane geschnitzt und sie von Generation zu Generation von einem Tiefseejäger zum nächsten weitergegeben. Es sind Talismane des Glücks oder der Tapferkeit, von der jede Familie seine eigenen hat.\n\nDas ist der Meinige. Ich kann ihn niemandem vererben. Ich möchte, dass Ihr ihn nehmt.", sourceObjective = "Nehmt ein Geschenk von Eurem Begleiter an.", completion = "Das ist ein Glückstalisman, er wurde über viele Jahre in unserer Gemeinschaft weitergegeben.\n\nBis jetzt hat er mir nicht viel Glück gebracht, bis er Euch zu mir geführt hat.\n\nEs wäre nur recht und billig, wenn Ihr ihn jetzt weiter tragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56217] = { id = 56217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezähmte Wildheit", description = "Während unserer gemeinsamen Zeit habe ich viel gelernt. Sowohl über meine eigenen Fähigkeiten als auch über Euer Volk.\n\nIm Angesicht der Gefahr seid Ihr genauso selbstlos wie mein Volk. Wir sind aus dem gleichen Holz.\n\nIch richte seit einiger Zeit einen Schnappdrachenwelpen ab, den ich einst gefunden habe. Er ist ein gutes Reittier und ich habe nur auf einen Jäger gewartet, der würdig ist, ihn zu reiten. Ich glaube, diesen Jäger habe ich jetzt gefunden.\n\nHier, er gehört Euch.", sourceObjective = "Nehmt ein Geschenk von Eurem Begleiter an.", completion = "Passt auf, wenn Ihr ihn füttert. Sein Gift ist für Freund und Feind gleichermaßen gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[56218] = { id = 56218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schönheit der Tiefen", description = "Ich habe viele Feinde getötet und viel Blut auf dem Sand vergossen. Seit ich an Eurer Seite kämpfe, haben sich meine Fähigkeiten unglaublich verbessert.\n\nAber lasst uns nicht vergessen, dass dies einst ein Ort des Friedens war. Mein Volk wandelte einst friedlich und ungestört in diesen Höhlen und zwischen diesen Riffen.\n\nIn diesen Tiefen ist die Schönheit überall um uns herum. Nehmt Euch einen Moment, setzt Euch und genießt die ruhige Umgebung. Seht nur, eine Krabbe mit einem farbig schimmernden Panzer.\n\nSeht Ihr? Hier gibt es auch Schönes, sogar jetzt.", sourceObjective = "Nehmt ein Geschenk von Eurem Begleiter an.", completion = "Nehmt diese Krabbe. Mag sie ein Symbol für die einstige Schönheit dieses Ortes sein.\n\nMit Eurer Hilfe wird es bald wieder so sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56219] = { id = 56219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Tränen", description = "Wir kämpfen nun schon eine Weile Seite an Seite. Ich hätte niemals gedacht, dass ein alter Recke wie ich noch etwas dazulernen kann, wenn es um das Töten von Naga geht. So kann man sich irren.\n\nIch muss Euch etwas zeigen...\n\n<Vim holt ein Buch aus seiner Tasche.>\n\nWir dürfen niemals vergessen.\n\nIch habe so viele Namen in diesem Buch niedergeschrieben. Es sind alles Namen von Entfesselten. Sie sind alle von uns gegangen.\n\nIch werde ihre Namen niemals vergessen.\n\nIhr sollt es nun haben. Erzählt alles weiter. Erzählt, wer sie waren und was sie hier getan haben.", sourceObjective = "Nehmt ein Geschenk von Eurem Begleiter an.", completion = "Dieses Buch enthält die Namen von mutigen Kreaturen aller Arten, die uns geholfen haben, für uns gekämpft haben und für uns gestorben sind.\n\nHelft mir, ihr Andenken zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56222] = { id = 56222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Lady Naz'jess", description = "Gesucht wegen Angriffen auf die Bevölkerung von Nazjatar!\n\nLady Naz'jess drängt die Waffenmeister dazu, noch grausamere Geräte zu bauen.\n\nZuletzt wurde sie in der Umgebung der Terrasse der Zanj'ir gesehen. Äußerste Vorsicht ist geboten, sie ist sehr gefährlich!\n\nMeldet Euch nach Abschluss dieser Mission bei Seerufer Unow für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Lady Naz'jess.", progress = "Ist das Ende ihres Kommandos gekommen?", completion = "Gute Arbeit, {class}. Lady Naz'jess war den Leuten hier ein echter Dorn im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[56223] = { id = 56223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kommandant Sarj'eth", description = "Gesucht wegen Angriffen auf die Bevölkerung von Nazjatar!\n\nKommandant Sarj'eth hat versucht, viele Überlebende der Horde zu versklaven.\n\nEr befehligt Sklaventreiber auf der Terrasse der Zanj'ir. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Seerufer Unow für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Kommandat Sarj'eth.", progress = "Ist der mutige Kommandant endlich am Ende seiner Tage angekommen?", completion = "Sarj'eth war ein hoch dekorierter Kommandant der Naga. \n\nDiese Leute werden besser schlafen, wenn er nicht mehr ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[56224] = { id = 56224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Lord Ha'kass", description = "Gesucht wegen Angriffen auf die Bevölkerung von Nazjatar!\n\nLord Ha'kass hat versucht, viele Überlebende der Horde zu versklaven.\n\nEr befehligt Sklaventreiber bei der Zanj'irbrandung. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Seerufer Unow für Eure Belobigung.", sourceObjective = "Holt den Kopf von Lord Ha'kass.", progress = "Habt Ihr den Bösewicht gefunden?", completion = "Abschaum wie er sollte nicht ungestraft davonkommen.\n\nIhr habt die Welt gerade zu einem etwas besseren Ort gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56225] = { id = 56225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Lady Narjiss", description = "Gesucht wegen Angriffen auf die Horde!\n\nLady Narjiss ist für mehrere Raubzüge und hinterhältige Überfälle gegen unsere Soldaten verantwortlich.\n\nZuletzt wurde sie in der Umgebung der Terrasse der Zanj'ir gesehen. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Seerufer Unow für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Lady Narjiss.", progress = "Habt Ihr sie zum Verstummen gebracht?", completion = "Lady Narjiss hat ihre Dunkelheit mit sich gebracht. Jetzt gibt es wieder etwas mehr Licht in der Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56226] = { id = 56226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Gler'thogg", description = "Gler'thogg ist für den Tod und die Folter vieler Entfesselter verantwortlich.\n\nSie haben ihren Schmerz mit uns geteilt. Bringt mir sein Auge.\n\nEr lauert in den Tunneln der Tiefennattern. Seid extrem vorsichtig!\n\nMeldet Euch nach Abschluss dieser Mission bei Seerufer Unow für Eure Belobigung.", sourceObjective = "Beschafft Gler'thoggs Auge.", progress = "Ist das Eure erste Enukleation?", completion = "Dieser tentakelgespickte Schrecken wird sie nicht mehr foltern.", sourceObjectiveStatus = "unverified-source-field" }
quests[56227] = { id = 56227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Inquisitor Ithriza", description = "Gesucht wegen Angriffen auf die Horde!\n\nInquisitor Ithriza ist für mehrere Raubzüge und hinterhältige Überfälle gegen unsere Soldaten verantwortlich.\n\nZuletzt wurde er in der Nähe des Drachenzahnbeckens gesehen. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Seerufer Unow für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Inquisitor Ithriza.", progress = "Habt Ihr ihn auf seinen Platz verwiesen?", completion = "Ein Foltermeister tot. Aber so viele leben noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[56231] = { id = 56231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkte Truhe", description = "Die schwer verstärkte Truhe wurde von den Naga hergestellt und scheint durch eine Art schweres Schloss gesichert zu sein.\n\nVerstärkung hin oder her, es wird immer noch einen Schlüssel benötigt, um das Schatzversteck aufzuschließen.\n\nDer Schlüssel befindet sich wahrscheinlich bei einem der Nagakommandanten in der Nähe.", sourceObjective = "Findet den Schlüssel zu dem Nagaschatz.", progress = "Die Truhe ist verschlossen und muss mit einem Schlüssel geöffnet werden.", completion = "Ihr dreht den Schlüssel und hört, wie die schweren Riegel der Truhe mit beachtlicher Kraft zurückschnappen...", sourceObjectiveStatus = "unverified-source-field" }
quests[56232] = { id = 56232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerentruhe", description = "Die schwer verstärkte Truhe wurde von den Naga hergestellt und scheint durch eine Art magisches Schloss gesichert zu sein.\n\nMagische Verstärkung hin oder her, es wird immer noch einen Schlüssel benötigt, um das Schatzversteck aufzuschließen.\n\nDer Schlüssel befindet sich wahrscheinlich bei einem der Nagakommandanten in der Nähe.", sourceObjective = "Findet den Schlüssel zu dem Nagaschatz.", progress = "Die Truhe ist verschlossen und muss mit einem Schlüssel geöffnet werden.", completion = "Die magische Barriere löst sich auf, als Ihr den Schlüssel ins Schloss steckt...", sourceObjectiveStatus = "unverified-source-field" }
quests[56233] = { id = 56233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Truhe", description = "Die schwer verstärkte Truhe wurde von den Naga hergestellt und scheint durch eine Art magisches Schloss gesichert zu sein.\n\nMagische Verstärkung hin oder her, es wird immer noch einen Schlüssel benötigt, um das Schatzversteck aufzuschließen.\n\nDer Schlüssel befindet sich wahrscheinlich bei einem der Nagakommandanten in der Nähe.", sourceObjective = "Findet den Schlüssel zu dem Nagaschatz.", progress = "Die Truhe ist verschlossen und muss mit einem Schlüssel geöffnet werden.", completion = "Die magische Barriere löst sich auf, als Ihr den Schlüssel ins Schloss steckt...", sourceObjectiveStatus = "unverified-source-field" }
quests[56234] = { id = 56234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde in der Not", description = "Ich glaube nicht, dass wir Priscilla heute zum letzten Mal gesehen haben, aber zumindest stellt sie jetzt keine unmittelbare Gefahr mehr dar.\n\nWir müssen unseren nächsten Schritt genau überdenken. In der Zwischenzeit sollten wir unsere Beziehung zu unseren neuen Verbündeten, den Ankoanern, vertiefen. Arbeitet mit ihnen, um die Gegend zu sichern und ihre Fähigkeiten zu verbessern. Noch haben wir es nicht überstanden.\n\nIch fürchte die größte Schlacht steht uns noch bevor. Lasst uns ihnen zeigen, dass wir es zusammen mit Azsharas Streitkräften aufnehmen und sie sogar besiegen können!", sourceObjective = "Unterstützt Eure Verbündeten in Nazjatar, indem Ihr mit Scharfseher Ori, Jäger Akana und Klingenkämpfer Inowari insgesamt 3000 Erfahrungspunkte erhaltet.", completion = "Gute Arbeit. Während Ihr unterwegs wart, habe ich mit Shandris gesprochen, und ich glaube, sie hat eine gute Idee, wie wir unsere Anstrengungen effektiver gestalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[56235] = { id = 56235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein nach Nazjatar", description = "Es gibt viel zu tun, {name}. Aber unsere Streitmacht ist erschöpft und braucht eine Ruhepause. Entscheidungen, die man müde trifft, sind selten gute.\n\nDiese \"Entfesselten\" haben angeboten, uns mit den Truppen, die sie haben, zu unterstützen. Wenn wir gegen Azsharas Truppen hier unten überleben wollen, müssen wir unsere neuen Verbündeten unterstützen.\n\nHelft einem ihrer Jäger bei seinen Aufgaben. Wir bleiben hier und diskutieren unsere nächsten Schritte.", sourceObjective = "Unterstützt Eure Verbündeten in Nazjatar, indem Ihr einen auf Rang 3 bringt.", completion = "Ausgezeichnete Arbeit. Eure Bemühungen haben uns geholfen, unsere Vorräte aufzustocken und unseren Verbündeten etwas dringend benötigte Kampferfahrung verschafft.\n\nSie haben uns diesen Gegenstand überlassen. Er scheint von magischer Natur zu sein. Ich kann seine Macht nicht bändigen, aber vielleicht ist Euer Herz von Azeroth dazu in der Lage. Nehmt ihn. Möge er uns gute Dienste leisten an diesem seltsamen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[56236] = { id = 56236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erloschen, aber nicht erledigt", description = "Aschenwind wird uns vorerst nicht weiter stören, aber unsere Situation bleibt bedrohlich.\n\nIch muss unseren nächsten Schritt überdenken, {name}. In der Zwischenzeit sollten wir unsere Beziehung zu unseren neuen Verbündeten, den Entfesselten, vertiefen. Erprobt ihre Fähigkeiten im Kampf und trainiert sie so gut Ihr könnt. Wir werden sie in den kommenden Schlachten brauchen.\n\nWir werden ihnen zeigen, dass sich unseren vereinten Kräften kein Hindernis in den Weg stellen kann.", sourceObjective = "Unterstützt Eure Verbündeten in Nazjatar, indem Ihr mit Vim Salzherz, Poen Kiembrack und Neri Scharffinne insgesamt 2.400 Erfahrungspunkte erhaltet.", completion = "Gute Arbeit. Während Ihr unterwegs wart, konnte ich einige Fortschritte bei der Suche nach Eurem nächsten Ziel machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56239] = { id = 56239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Silbermesser", description = "<Dieses silberne Messer, das Ihr in einer Truhe gefunden habt, ist klein und weist dezente Verzierungen auf.\n\nEs wurde wahrscheinlich zum Essen oder zur Essenszubereitung genutzt und nicht für den Kampf. Aber wofür sollten die Naga so ein Messer brauchen?\n\nVielleicht weiß einer der Ankoaner mehr...>", sourceObjective = "Fragt die Ankoaner nach dem Messer.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr da?\n\nAh, ja. Ihr habt das in einer der Truhen gefunden? Wir haben ähnliche Dinge gefunden. Besteck, dekorative Teller und ähnliches. Vielleicht gehören sie gar nicht den Naga? Es bleibt ein Rätsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[56240] = { id = 56240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Silbermesser", description = "<Dieses silberne Messer, das Ihr in einer Truhe gefunden habt, ist klein und weist dezente Verzierungen auf.\n\nEs wurde wahrscheinlich zum Essen oder zur Essenszubereitung genutzt und nicht für den Kampf. Aber wofür sollten die Naga so ein Messer brauchen?\n\nVielleicht weiß einer der Entfesselten mehr...>", sourceObjective = "Fragt die Entfesselten nach dem Messer.\n\nBereitgestellter Gegenstand:", completion = "Na, was haben wir denn da?\n\nAh ja, in diesen Truhen da draußen kann man viele schöne Dinge finden. Es sind wohl keine Gegenstände der Naga. Und genau das ist das Komische daran. Jemand anders muss sie hier zurückgelassen haben.\n\nIch nehme Euch das aber gerne ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[56241] = { id = 56241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konservierte Hinweise", description = "Wir haben Truhen ähnlich denen, die Ihr beschreibt, gefunden. Wir glauben, dass sie von jemandem zurückgelassen wurden, der vor den Naga hier war.\n\nManche sind sogar mit merkwürdigen arkanen Runen verschlossen. Die Naga interessieren sich scheinbar am meisten für genau diese.\n\nIch weiß nicht viel über sie, außer dass man sie meistens in den Ruinen der Stadt findet.\n\nWenn Ihr deren Geschichte entwirren wollt, würde ich dort anfangen.", sourceObjective = "Sucht in Zin-Azshari nach Informationen über die merkwürdigen arkanen Truhen.", completion = "<Ein einfaches Buch mit einer kleinen Anzahl Runen entlang des Buchrückens. Es sieht für diese Ruinen erstaunlich gut erhalten aus.\n\nBei weiterer Untersuchung bemerkt Ihr, dass es sich wohl um das Tagebuch eines der Stadtbewohner handelt. Es besteht kein Zweifel daran, dass die Magie, die es schützt, für die Verwendung in den langen Lebensspannen der Elfen gedacht war.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56242] = { id = 56242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konservierte Hinweise", description = "Wenn Ihr noch andere Sachen in den Truhen findet, die Ihr nicht braucht, bringt sie einfach zu mir.\n\nIch habe selbst ein paar davon gefunden. Sie gehören anscheinend nicht den Naga, sondern jemandem, der zuvor in der Stadt gelebt hat.\n\nManche sind mit arkaner Magie verschlossen. Wahrscheinlich sind in diesen Truhen wertvolle Dinge zu finden, weshalb auch die Naga sie immer mitnehmen.\n\nViel mehr weiß ich nicht. Wenn Ihr mehr über ihre Geschichte erfahren wollt, würde ich dort in den Ruinen der Stadt herumschnüffeln.", sourceObjective = "Sucht in Zin-Azshari nach Informationen über die merkwürdigen arkanen Truhen.", completion = "<Ein einfaches Buch mit einer kleinen Anzahl Runen entlang des Buchrückens. Es sieht für diese Ruinen erstaunlich gut erhalten aus.\n\nBei weiterer Untersuchung bemerkt Ihr, dass es sich wohl um das Tagebuch eines der Stadtbewohner handelt. Es besteht kein Zweifel daran, dass die Magie, die es schützt, für die Verwendung in den langen Lebensspannen der Elfen gedacht war.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56243] = { id = 56243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebücher der Toten", description = "<Die Verzauberung dieses Buchs ist intakt, aber sie wird schwächer. Es sieht nach dem Tagebuch eines Stadtbewohners aus. Ihr schlagt eine beliebige Seite auf...>\n\nDann hatte er die Dreistigkeit, unseren Beschwörungskreis zu betreten und uns aufzufordern, seinen Studienort sofort zu verlassen. Wer betritt denn freiwillig das Chaos eines Beschwörungsrituals? Er ist verrückt. Deswegen nennen wir ihn jetzt den verrückten Mardivas.\n\nNatürlich wurde er von einem niederen Dämon ins Bein gebissen, und...\n\n<Der Text geht weiter. Er ist nicht sehr nützlich. Ihr glaubt, dass es sicherlich noch mehr solcher Tagebücher gibt.>", sourceObjective = "Sucht in Zin-Azshari in Nazjatar nach weiteren Tagebüchern.", completion = "<Ihr seht ein leuchtendes Schloss und daneben Mardivas' Tagebuch. Ihr seht Euch die letzten Seiten an.>\n\nDie Runenschaltungen wurden stabilisiert und so angeordnet, dass sie nur von einer Person mit meinem logischen Scharfsinn entschlüsselt werden können.\n\nOh, könnte man nur die Gesichter der erfolglosen Diebe sehen! \n\nJa, ja, ja, das ist es! Ich werde an einem Zauberschutz arbeiten, mit dem man die Diebe in Aktion sehen kann. Ich bin wirklich ein Genie.\n\nIch brauche nur ein wenig mehr Zeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[56244] = { id = 56244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebücher der Toten", description = "<Die Verzauberung dieses Buchs ist intakt, aber sie wird schwächer. Es sieht nach dem Tagebuch eines Stadtbewohners aus. Ihr schlagt eine beliebige Seite auf...>\n\nDann hatte er die Dreistigkeit, unseren Beschwörungskreis zu betreten und uns aufzufordern, seinen Studienort sofort zu verlassen. Wer betritt denn freiwillig das Chaos eines Beschwörungsrituals? Er ist verrückt. Deswegen nennen wir ihn jetzt den verrückten Mardivas.\n\nNatürlich wurde er von einem niederen Dämon ins Bein gebissen, und...\n\n<Der Text geht weiter. Er ist nicht sehr nützlich. Ihr glaubt, dass es sicherlich noch mehr solcher Tagebücher gibt.>", sourceObjective = "Sucht in Zin-Azshari in Nazjatar nach weiteren Tagebüchern.", completion = "<Ihr seht ein leuchtendes Schloss und daneben Mardivas' Tagebuch. Ihr seht Euch die letzten Seiten an.>\n\nDie Runenschaltungen wurden stabilisiert und so angeordnet, dass sie nur von einer Person mit meinem logischen Scharfsinn entschlüsselt werden können.\n\nOh, könnte man nur die Gesichter der erfolglosen Diebe sehen! \n\nJa, ja, ja, das ist es! Ich werde an einem Zauberschutz arbeiten, mit dem man die Diebe in Aktion sehen kann. Ich bin wirklich ein Genie.\n\nIch brauche nur ein wenig mehr Zeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[56245] = { id = 56245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzaubertes Schloss", description = "<Das Schloss scheint durch einen magischen Mechanismus gesichert zu sein.\n\nEs ist ganz offensichtlich eines von Mardivas' Objekten. Den Tagebüchern nach ist es vermutlich mit einem arkanen Rätsel verschlossen.\n\nIhr seht Euch im Raum um und entdeckt etwas Merkwürdiges im Wasser.>", sourceObjective = "Löst Mardivas' magisches Rätsel und entriegelt so das verzauberte Schloss.", completion = "<Das Rätsel ist gelöst und das Schloss springt mit einem zufriedenstellenden Klicken auf.\n\nAnscheinend hat Mardivas mehrere dieser Rätsel erschaffen, um seine Habseligkeiten sicher zu verstauen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56246] = { id = 56246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzaubertes Schloss", description = "<Das Schloss scheint durch einen magischen Mechanismus gesichert zu sein.\n\nEs ist ganz offensichtlich eines von Mardivas' Objekten. Den Tagebüchern nach ist es vermutlich mit einem arkanen Rätsel verschlossen.\n\nIhr seht Euch im Raum um und entdeckt etwas Merkwürdiges im Wasser.>", sourceObjective = "Löst Mardivas' magisches Rätsel und entriegelt so das verzauberte Schloss.", progress = "<Das Schloss summt.>", completion = "<Das Rätsel ist gelöst und das Schloss springt mit einem zufriedenstellenden Klicken auf.\n\nAnscheinend hat Mardivas mehrere dieser Rätsel erschaffen, um seine Habseligkeiten sicher zu verstauen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56247] = { id = 56247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzgeschichten", description = "<Ihr habt die Geschichte von Mardivas entdeckt, einem Zauberer, der einst in der Stadt lebte und magische Truhen hergestellt hat, die man in ganz Nazjatar verteilt finden kann.\n\nAnscheinend war er nicht sonderlich beliebt. Ihn störte das aber nicht, weil er die anderen Einwohner auch nicht wirklich mochte.\n\nIhr habt eines seiner \"unlösbaren\" arkanen Schlösser gefunden und entriegelt. Was Ihr dabei gelernt habt, kann sich auf Eurer Reise nur als nützlich erweisen.\n\nHandwerker Itanu wird das Ende dieser Geschichte sicher gerne hören wollen.>", sourceObjective = "Kehrt zu Handwerker Itanu in Nazjatar zurück.", completion = "Ah, was für ein schönes Ende dieser Geschichte. Ich danke Euch.\n\nIch habe mich schon ewig gefragt, warum man sein Geschirr wegschließen sollte. Wenn man aber seine Nachbarn weder mag noch ihnen traut, wird der Grund offensichtlich.\n\nTrotz all seiner Anstrengungen sind seine Schätze jetzt in Euren Händen. Wie amüsant.", sourceObjectiveStatus = "unverified-source-field" }
quests[56248] = { id = 56248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzgeschichten", description = "<Ihr habt die Geschichte von Mardivas entdeckt, einem Zauberer, der einst in der Stadt lebte und magische Truhen hergestellt hat, die man in ganz Nazjatar verteilt finden kann.\n\nAnscheinend war er nicht sonderlich beliebt. Ihn störte das aber nicht, weil er die anderen Einwohner auch nicht wirklich mochte.\n\nIhr habt eines seiner \"unlösbaren\" arkanen Schlösser gefunden und entriegelt. Was Ihr dabei gelernt habt, kann sich auf Eurer Reise nur als nützlich erweisen.\n\nFinderin Palta wird das Ende dieser Geschichte sicher gerne hören wollen.>", sourceObjective = "Kehrt zu Finderin Palta in Neuheim in Nazjatar zurück.", completion = "Hey, danke für die Information. Ich wollte schon immer wissen, was es mit diesen Truhen auf sich hat.\n\nIch habe natürlich nichts gegen geschenkte Schätze. Immer her damit.\n\nIch wette, es würde seine Muscheln zum Dampfen bringen, wenn er wüsste, dass Ihr am Ende all sein Zeug haben werdet, ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[56249] = { id = 56249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin der Schrottmeister", sourceObjective = "Gebt Jani den Mantel der Schrottmeisterin.", completion = "Hek hek hek. Danke fürs Tauschen, Zastamann.\n\nIch brauch das Ding eh nich'. Es is' zu muffig, zu mächtig. Nichts für Jani. Aber Ihr könnt es hab'n.\n\nJetzt geht. Ich hab hier zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[56250] = { id = 56250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin der Schrottmeister", sourceObjective = "Gebt Jani den Mantel der Schrottmeisterin.", completion = "Hek hek hek. Danke fürs Tauschen, Zastamann.\n\nIch brauch das Ding eh nich'. Es is' zu muffig, zu mächtig. Nichts für Jani. Aber Ihr könnt es hab'n.\n\nJetzt geht. Ich hab hier zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[56256] = { id = 56256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Alterac", description = "Die Forscherliga glaubt, dass es im Alteractal einige Artefakte von Interesse gibt. Allerdings werden uns die Orcs des Frostwolfklans wohl kaum danach forschen lassen. Wir können es der Horde jedoch nicht erlauben, unseren Forschungsbemühungen im Weg zu stehen! Vernichtet den General der Frostwölfe, Drek'Thar. Mit seinem Tod werden die Orcs ihren Vorteil verlieren.\n\nDrek'Thar hält sich in der Burg Frostwolf auf, im Süden des Alteractals. Bezwingt ihn und kehrt dann zu mir zurück.", sourceObjective = "Betretet das Alteractal und bezwingt den Hordengeneral Drek'Thar.", sourceObjectiveStatus = "unverified-source-field" }
quests[56257] = { id = 56257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht ums Alteractal", description = "Die Sturmlanzenzwerge und ihre Verbündeten sind in das Alteractal eingefallen und wir müssen sie vertreiben! Um die Schlacht ums Alteractal gewinnen zu können, müssen wir ihren General töten, Vanndar Sturmlanze!\n\nIhr werdet Vanndar in Dun Baldar, im Norden des Alteractals finden.\n\nTötet ihn, {name}, und kehrt dann zu mir zurück.", sourceObjective = "Betretet das Alteractal und bezwingt den Zwergengeneral Vanndar Sturmlanze.", completion = "Gute Arbeit, {name}! Die Sturmlanzen haben ihre närrische Invasion bereits verloren.\n\nHah! Das Einzige, was sie bisher erreicht haben, ist der Tod ihres Generals!", sourceObjectiveStatus = "unverified-source-field" }
quests[56258] = { id = 56258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivus der Waldlord", description = "Der Frostwolfklan wird durch eine Besudelung aus Elementarenergie geschützt. Ihre Schamanen stümpern mit Mächten herum, die uns sicherlich alle vernichten werden, wenn sie nicht im Zaum gehalten werden.\n\nDer Schaden ist zu groß geworden, als dass der Kreis ihn noch kontrollieren kann! Wir müssen Ivus zu Hilfe rufen.\n\nDie Soldaten der Frostwölfe tragen Elementarglücksbringer, die Sturmkristalle genannt werden. Wir können diese Glücksbringer nutzen, um Ivus zu beschwören. Zieht los und holt die Kristalle, {name}!", sourceObjective = "Tötet Mitglieder der Horde, erbeutet einen Sturmkristall und bringt ihn zu Erzdruidin Renferal im Alteractal.", progress = "Habt Ihr uns ein paar Kristalle mitgebracht, {name}?", completion = "Gut gemacht, {name}. Ich werde diese Kristalle dafür benutzen, die bereits angesammelte Magie noch weiter zu verstärken. Wenn sich am Ende genug Kraft gesammelt hat, werde ich die gesammelten Energien bündeln, um den Waldlord herbeizurufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56259] = { id = 56259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokholar der Eislord", description = "Ich komme aus Donnerfels, {race}. Cairne selbst hat dafür gesorgt, dass ich den Frostwolfklan in diesen schrecklichen Zeiten unterstütze.\n\nDoch lasst uns nicht noch mehr Zeit verschwenden. Ihr müsst unsere Feinde niederstrecken und mir ihr Blut bringen. Wenn Ihr ausreichend Blut gesammelt habt, dann kann das Ritual der Beschwörung beginnen.\n\nDer Sieg ist uns sicher, wenn der Lord der Elementare auf die Armee der Sturmlanzen losgelassen wird.", sourceObjective = "Tötet Mitglieder der Allianz, erbeutet Sturmlanzenblut und bringt es zu Primalistin Thurloga im Dorf der Frostwölfe im Alteractal.", progress = "Habt Ihr ein Angebot für uns?", completion = "Das Blut unserer Feinde wurde vergossen. Ich werde nun dieses Blut, mit dem restlichen gesammelten Blut vermischen. Sobald unser Opfer abgeschlossen ist, wird der Eislord diesen Hunden von den Sturmlanzen den ganzen Zorn des Frostwolfklans vor Augen führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[56260] = { id = 56260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Kraft", description = "In der Herzkammer wartet etwas Besonderes auf Euch, Champion.\n\nIch werde nicht verraten, was es ist, aber an Eurer Stelle würde ich so schnell wie möglich dort hingehen.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Haben wir eine Überraschung für Euch, Champion! Ihr werdet sie lieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[56261] = { id = 56261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Herzen", description = "Grüße, Champion von Azeroth.\n\nMUTTER hat Eure Fortschritte mit dem Herzen von Azeroth beobachtet und sie ist mit der Arbeit, die Ihr geleistet habt, um es stärker zu machen, sehr zufrieden.\n\nZumindest glauben wir das. Manchmal ist es schwer zu erkennen.\n\nEgal, kommt einfach zurück in die Herzkammer, sobald Ihr könnt. Es gibt noch viel zu tun.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Das Herz von Azeroth fühlt sich stärker an als je zuvor. Ich frage mich, was für Kräfte noch darin verborgen liegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[56262] = { id = 56262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Kammer", description = "Das Herz von Azeroth wird jeden Tag stärker, und das macht einen Riesenunterschied.\n\nBegebt Euch zur Herzkammer, Champion. Wir brauchen Eure Talente.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Das Herz von Azeroth erstaunt mich doch immer wieder. Gut gemacht, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[56263] = { id = 56263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Kraft", description = "In der Herzkammer wartet etwas Besonderes auf Euch, Champion.\n\nIch werde nicht verraten, was es ist, aber an Eurer Stelle würde ich so schnell wie möglich dort hingehen.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Haben wir eine Überraschung für Euch, Champion! Ihr werdet sie lieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[56264] = { id = 56264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krosse Krabben!", description = "{name}, Ihr kommt gerade rechtzeitig. Alles ist bereit für die Krabbenjagd!\n\nAlso gut... Ich weiß, was Ihr denkt. Ein Gründungsmitglied von D.E.H.T.A., das eine Jagd duldet?\n\nIch werde offen zu Euch sein, {name}. Ich habe einen Tresen voll mit hungrigen Murlocs, die nur drei Dinge fressen: Krabben, Fische und Leute.\n\nUnd wenn das nicht Grund genug ist: Wir haben eine Krabbenüberbevölkerung hier in der Gegend, und sie dezimieren die hiesige Käferlarvenpopulation!\n\nWie viele unschuldige Käferlarven müssen noch sterben, bevor wir etwas unternehmen, {name}?", sourceObjective = "Sammelt 12 Knisterscherenkrabben.", progress = "Wie viele unschuldige Käferlarven müssen noch sterben, bevor wir etwas unternehmen, {name}?", completion = "Das sind ja angenehme Scherereien, die Ihr mir da mitbringt.{name}. Gut gemacht! Bitte stellt die Kiste hinter den Tresen und ich kümmere mich um den Rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[56265] = { id = 56265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Bier nix los", description = "Diese nichtsnutzigen Blutflossen sind mit dem ganzen Bier abgehauen!\n\nIch habe mit verschiedenen Brauarten experimentiert, bei denen nur Zutaten aus Nazjatar verwendet werden, aber das ist noch nicht ausgereift. Vorläufig muss ich mich damit zufriedengeben, was ich aus dem Schiffswrack bergen kann.\n\nMeine Biervorräte waren schon begrenzt, aber jetzt ist dank dieser diebischen Blutflossenmurlocs alles weg! Wir werden hier ein paar ziemlich erboste Kunden haben, wenn wir das Bier nicht zurückbekommen.\n\nBitte holt das gestohlene Lagerbier aus dem Blutflossendorf zurück, bevor es zu spät ist!", sourceObjective = "Sammelt 12 Lagerbier mit \"Ozeanhauch\".", progress = "Bitte sagt mir, dass Ihr das Bier gefunden habt.", completion = "Gute Arbeit, {name}! Ihr habt fast das gesamte gestohlene Bier zurückgeholt. Diese Blutflossen machen mehr Ärger, als uns lieb sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[56266] = { id = 56266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mgglurkys Mugglrgl", description = "Mein Koch Mgglurky hat sein Mugglrgl verloren und weigert sich, zu arbeiten, ehe er es nicht zurückbekommt.\n\nIch habe einen Tresen voll mit hungrigen Murlocs und solange Mgglurky nicht kocht, habe ich nichts, um sie zu beköstigen. Wenn Mgglurky nicht bald sein Mugglrgl findet, haben wir hier einen Aufstand am Hals!\n\nIch weiß ja nicht, wie es Euch geht, aber ich habe keine Lust, heute Abend das Hauptgericht zu sein.\n\nHier haben vorhin einige Blutflossen herumgelungert. Durchsucht das Blutflossendorf nach dem Mugglrgl und bringt es mir, wenn Ihr es gefunden habt.", sourceObjective = "Holt Mgglurkys Mugglrgl aus dem Blutflossendorf zurück.", progress = "Wenn Mgglurky nicht bald sein Mugglrgl findet, haben wir hier einen Aufstand am Hals!", completion = "Ihr habt es gefunden! Also das ist ein Mugglrgl? Aus irgendeinem Grund dachte ich, es wäre größer. Mgglurky wird sehr glücklich sein, dass Ihr es zurückgebracht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56267] = { id = 56267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflüster von N'Zoth", description = "Fragt Ihr Euch, warum ich hier in der Herzkammer bin?\n\nNatürlich kam ich freiwillig her, aber eine Zeit lang gab es eine große Suche nach mir.\n\nKalecgos weiß noch, wie das lief. Sprecht mit ihm, wenn Ihr selbst erleben möchtet, wie ich sowohl dem Sprecher als auch dem Alten Gott immer einen Schritt voraus war.", sourceObjective = "Sprecht mit Kalecgos in der Herzkammer.", completion = "Ich wusste, dass N'Zoth mächtig ist, doch Ebenhorn in der Sicherheit der Kammer zu erwischen...\n\nWir müssen etwas dagegen unternehmen. Keiner von uns ist sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[56301] = { id = 56301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ran ans Gold", description = "Ich habe viele Geschichten über tote Väter, Mütter und Familienschätze gehört. Alles Märchen. Wir sind alle hier, um jegliches Piratengold abzugreifen, bevor diese Mechaidioten es in die Finger bekommen! \n\nWenn es hier irgendwo Gold gibt, dann sicher in dieser fetten Truhe, die von den Murlocs bewacht wird.\n\nTötet ihren Anführer, leert die Truhe und wir machen halbe-halbe. Der Plan ist schließlich von mir.", sourceObjective = "Bergt den Schatzsack der Murlocs.", progress = "Holt das Gold!", completion = "Mit Euch kann man arbeiten. Hier ist Euer Anteil!", sourceObjectiveStatus = "unverified-source-field" }
quests[56304] = { id = 56304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch geboren, tief gefallen", description = "Ihr da. Ich könnte Hilfe brauchen.\n\nAlle in meiner alten Heimat haben ihr Leben in der Flut verloren. Ich weiß immer noch nicht, was aus meinem Vater Corin geworden ist.\n\nDie Rückkehr zu den Anwesen bereitet mir Schmerz und zudem gibt es rachsüchtige Geister, die dieses einst so makellose Gebiet heimsuchen. Helft Ihr mir dabei, herauszufinden, was mit meinem Vater geschehen ist?", sourceObjective = "Begleitet Kelya Mondsturz in die Anwesen der Hochgeborenen und sucht nach dem Geist ihres Vaters.", completion = "{name}, Corin wird von dieser Schattenzauberin der Naga gefoltert.\n\nWir müssen etwas unternehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[56305] = { id = 56305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehen wir fischen!", description = "Wir könnte Hilfe von ein paar Freunden brauchen, um diesen Fisch an Land zu bekommen!\n\nBenutzt den Köder der hundert Klafter, sobald Ihr bereit seid.", sourceObjective = "Fangt den Tiefseeschlund und tötet ihn!", completion = "Der Stoff für bestes Anglerlatein!", sourceObjectiveStatus = "unverified-source-field" }
quests[56306] = { id = 56306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familienjuwelen", description = "Diese verflixten Piraten haben meine Juwelen gestohlen... äh, ich meine, die Juwelen meiner Schwester... äh oder waren es die meiner Mutter? Genau. So war es!\n\nDer Punkt ist, sie haben sie gestohlen und jetzt ist alles da draußen verstreut im Matsch... und in den Schatztruhen. Vielleicht auch bei ein paar Robotern und Murlocs.\n\nMeine Mutter ist nicht gierig. Sie will doch nur ein paar Halsketten aus Gold und eine Menge Diamanten. Ich bezahle sie Euch auch.", sourceObjective = "Holt 75 Familienjuwelen zurück.", progress = "Stehlt die Juwelen für meinen Bruder zurück!", completion = "All diese Juwelen für mich!", sourceObjectiveStatus = "unverified-source-field" }
quests[56308] = { id = 56308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Ausgegrabene Aqir", description = "Unsere Stellung wird überrannt. Die Aqir branden in Massen heran, wie ich sie noch nie zuvor gesehen habe!\n\nIch bin nicht sicher, wie lange wir hier noch durchhalten können. Ihr müsst sie für uns zum Rückzug zwingen!", sourceObjective = "Schlagt den Angriff der Aqir in Uldum zurück.", progress = "Unsere Leute können nicht ewig durchhalten.", completion = "Ihr habt unser Lager gerettet und höchstwahrscheinlich auch unser Volk.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56309] = { id = 56309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadt der ertrunkenen Freunde", description = "Champion, ich habe ein persönliches Anliegen an Euch, mit dessen Erledigung ich keine meiner Wachen beauftragen kann.\n\nEs geht nicht um die Allianz oder den Krieg... nicht mal um den Kampf gegen Azshara. Das ist ein persönlicher Gefallen.\n\nAls ich ein kleines Mädchen war, wurde meine Stadt von der Legion angegriffen. Viele der Überlebenden sind hierher geflohen, nur um dann zu ertrinken oder Schlimmeres. Ich muss wissen, was aus ihnen geworden ist.\n\nHelft Ihr mir bei der Suche nach Hinweisen?", sourceObjective = "Helft Shandris Mondfeder beim Durchsuchen des Ertrunkenen Markts.", completion = "Er... könnte hier sein. Janius... nein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56310] = { id = 56310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadt der ertrunkenen Freunde", description = "Champion, ich habe ein persönliches Anliegen an Euch. Dabei geht es nicht um die Horde oder um den Krieg.\n\nEs ist über zehntausend Jahre her, dass ich das letzte Mal auf diesen Straßen gewandelt bin. Ich kannte viele dieser Leute. Einige habe ich sogar selbst ausgebildet.\n\nBegleitet Ihr mich, während ich ihre Schicksale ergründe? Die Straße ist gefährlich und ich weiß nicht, ob ich ruhig bleiben kann, wenn ich den alten Kummer heraufzubeschwören versuche.", sourceObjective = "Helft der Ersten Arkanistin Thalyssra beim Durchsuchen des Ertrunkenen Markts.", completion = "Sivara. Oh Sivara. Sie war eine der besten Schülerinnen, die ich je hatte. Ich muss sie finden und sicherstellen, dass sie nicht in ewiger Folter gefangen ist wie die anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56311] = { id = 56311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Ertrinken", description = "Bleibt dicht bei mir, Champion. Ich habe da einige Gegenstände, die uns kurze Zeit gegen magische Angriffe schützen können. Allerdings war Azshara die größte Magierin, die unser Volk jemals hervorgebracht hat...\n\nIch glaube kaum, dass diese Objekte ihrer Macht lange entgegenwirken können... oder danach noch brauchbar sein werden.\n\nSprecht mit mir, wenn Ihr bereit seid.", sourceObjective = "Begleitet Shandris Mondfeder durch den Ertrunkenen Markt.", completion = "Die Flut ist vorerst gestoppt. Das ist gut, weil ich nicht glaube, dass ich genug Ladungen in diesen Gegenständen übrig habe, um uns vor einer weiteren Welle dieser Art zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56312] = { id = 56312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Ertrinken", description = "Königin Azshara beobachtet uns genau. Wir müssen vorsichtig vorgehen.\n\nIch weiß nicht, was sie noch versuchen wird, aber bleibt nahe bei mir. Egal, was auch auf uns zukommt, wir müssen da durch, wenn wir Sivara finden wollen.\n\nSprecht mit mir, wenn Ihr dazu bereit seid.", sourceObjective = "Eskortiert die Erste Arkanistin Thalyssra durch den Ertrunkenen Markt.", completion = "Die Flut ist vorerst gestoppt. Das ist gut, weil meine Kraft so gut wie am Ende ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[56313] = { id = 56313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsbringerin", description = "Wir stehen mitten in äußerst mächtiger Magie. Ein Widerhall von etwas, das Azshara vor langer Zeit getan hat.\n\nWenn Ihr den Mut habt, mit diesem Echo zu kommunizieren, werde ich währenddessen Wache stehen.", sourceObjective = "Haltet Zwiesprache mit der Erinnerung an den Pakt.", progress = "Seid auf alles gefasst.", completion = "Wir haben schon seit Langem vermutet, welche Wahl Azshara getroffen hat. Die Frage ist nur, weshalb sie uns das hier zeigt. Welches Spiel treibt sie dieses Mal?", sourceObjectiveStatus = "unverified-source-field" }
quests[56314] = { id = 56314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsbringerin", description = "Wir stehen mitten in äußerst mächtiger Magie. Ein Widerhall von etwas, das Azshara vor langer Zeit getan hat.\n\nWenn Ihr den Mut habt, mit diesem Echo zu kommunizieren, werde ich währenddessen Wache stehen.", sourceObjective = "Haltet Zwiesprache mit der Erinnerung an den Pakt.", progress = "Seid auf alles gefasst.", completion = "Wir haben schon seit Langem vermutet, welche Wahl Azshara getroffen hat. Die Frage ist nur, weshalb sie uns das hier zeigt. Welches Spiel treibt sie dieses Mal?", sourceObjectiveStatus = "unverified-source-field" }
quests[56315] = { id = 56315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben ihre Wahl getroffen", description = "Es hat Azshara nicht gereicht, die Welt zu zerbrechen. Sie musste den Rest unseres Volkes hier auch noch ins Verderben stürzen!\n\nDiejenigen, die keine Naga werden wollten, steckten in einem grauenhaften Halbtod fest, dazu verdammt, diese versunkenen Ruinen heimzusuchen.\n\nIch habe beinahe Angst davor, was wir vorfinden werden, wenn wir meinen Freund aufspüren.\n\nMoment, habt Ihr etwas gehört?", sourceObjective = "Helft Shandris Mondfeder.", progress = "Dreifach verdammte Azshara. Ihre Bosheit kennt keine Grenzen.", completion = "Ich kann Euch gar nicht genug danken, dass Ihr mir geholfen habt, mich von meinem Freund zu verabschieden, {name}. Ich stehe in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[56316] = { id = 56316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben ihre Wahl getroffen", description = "Es hat Azshara nicht gereicht, die Welt zu zerbrechen. Sie musste den Rest unserer Leute hier auch noch ins Verderben stürzen!\n\nDiejenigen, die keine Naga werden wollten, steckten in einem grauenhaften Halbtod fest, dazu verdammt, diese versunkenen Ruinen heimzusuchen.\n\nIch habe beinahe Angst davor, Sivara zu finden.\n\nMoment, habt Ihr etwas gehört?", sourceObjective = "Helft der Ersten Arkanistin Thalyssra.", progress = "Dreifach verdammte Azshara. Ihre Bosheit kennt keine Grenzen.", completion = "Sivara hätte uns jederzeit besiegen können. Warum spielen sie mit uns? \n\nAuf jeden Fall stehe ich erneut in Eurer Schuld, Champion. Ich danke Euch für Eure Hilfe, auch wenn die Antworten, die wir gefunden haben, viel schrecklicher waren, als ich es jemals erwartet hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[56319] = { id = 56319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blitzladevertrag", description = "Entzückende Nachrichten, liebes Versuchsobjekt!\n\nMein lieber Bruder und ich haben 65 Prozent der Funktionalität unseres Forschungslabors wiederhergestellt.\n\nWir hoffen, dass wir bald wieder zu unserem normalen Forschungsplan zurückkehren können. Allerdings brauchen wir eine frische Ladung mutiger Versuchsobjekte, die uns dabei helfen, die Gesetze der Natur und der Wissenschaft an ihre Grenzen zu bringen!\n\nHabt Ihr Interesse? Dann müsst Ihr lediglich unserem mündlichen Standardvertrag zustimmen...", sourceObjective = "Stimmt dem Blitzladevertrag zu.", completion = "Willkommen im Blitzladeteam, liebes Versuchsobjekt.\n\nWas für ein großer Tag heute ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[56320] = { id = 56320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Aufladung ist kostenlos!", description = "Spürt Ihr die Energie, die hier durch den Boden fließt, mein liebes Versuchsobjekt?\n\n<Flip atmet tief ein.>\n\nOhne das ständige elektrische Knistern würde nichts von Bedeutung existieren.\n\nMeine liebe Schwester und ich haben eine Hochspannungsleitung angezapft, die direkt hier unter uns verläuft, aber der eigentliche Saft ist drüben in Bondos Hof. Dieser Egoist will die ergiebigste Stromquelle in Mechagon ganz für sich allein haben!\n\nWenn Ihr Eure leeren Energiezellen aufladen wollt, müsst Ihr Euch Zugriff auf die Aufladestation von Flux verschaffen.", sourceObjective = "Verschafft Euch Zugriff auf die Aufladestation in Bondos Hof und nutzt sie dann, um eine leere Energiezelle aufzuladen.", completion = "Flux ist grob, fies und obendrein noch ganz schön mies.\n\nSeid vorsichtig mit dieser wundersamen Energiezelle. Die kleinen Strompacks sind hier draußen in Mechagon ihr Gewicht in Gold wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[56321] = { id = 56321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corin retten", description = "Mein Vater wird von dieser Nagahexe gefoltert!\n\n{name}, Ihr müsst mir dabei helfen, ihn zu retten. Wir dürfen nicht zulassen, dass sein Geist von den Naga versklavt wird.\n\nBeeilt Euch! Wenn wir nicht sofort handeln, droht ihm dasselbe Schicksal wie den anderen!", sourceObjective = "Besiegt Schattenzauberin Vixtris.", completion = "Ich danke Euch, {name}. Mein Vater und ich sind Euch ewig dankbar für das, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56322] = { id = 56322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maßvoller Bierlementar", description = "<Als das Gebräu in seinen natürlichen, inaktiven Zustand zurückkehrt, erscheint ein seltsames Fass.\n\nVielleicht weiß Braumeister Tsing mehr über diesen merkwürdigen Vorfall.>", sourceObjective = "Sprecht mit Braumeister Tsing auf dem Braufestplatz.", completion = "Alles trägt einen Geist in sich. Von den Wolken im Himmel bis zum kleinen Regenwurm in der Erde. Das Leben ist auf der ganzen Welt miteinander verwoben.\n\nMit dem Brauen ist es nicht anders. Wir brauen mit so viel Liebe und Hingabe... da bedarf es nur eines kleinen Funkens, um Leben direkt vor unseren Augen entstehen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56324] = { id = 56324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Aufladung kostet!", description = "Ihr wollt ein paar Energiezellen an unserem Energieturm aufladen?\n\nDas wundert mich nicht, das wollen alle.\n\nUnd jeder muss dafür ZAHLEN. Habt Ihr das verstanden, oder braucht Ihr eine Wiederholung?\n\n<Flux spuckt hinter sich.>\n\nEs ist wohl das erste Mal für Euch. Für solche Grünschnäbel hat Bondo ein ganz besonderes Angebot.\n\nEine kleine Zugriffsgebühr und nur eine Aufladung.\n\nAbgemacht? Ein besseres Angebot bekommt Ihr nicht.", sourceObjective = "Zahlt Flux' Zugriffsgebühr und nutzt dann die Aufladestation, um die leere Energiezelle aufzuladen.", progress = "Ihr wollt ein paar Energiezellen an unserem Energieturm aufladen?\n\nDas wundert mich nicht, das wollen alle.\n\nUnd jeder muss dafür ZAHLEN. Habt Ihr das verstanden, oder braucht Ihr eine Wiederholung?\n\n<Flux spuckt über ihre Schulter.>\n\nEs ist wohl das erste Mal für Euch. Für solche Grünschnäbel hat Bondo ein ganz besonderes Angebot.\n\nEine kleine Zugriffsgebühr und nur eine Aufladung.\n\nEin besseres Angebot bekommt Ihr nicht.", completion = "Ihr dürft genau einmal aufladen.\n\nHaltet Eure leere Energiezelle an die Aufladestation, um fortzufahren.\n\nKein doppeltes Aufladen. Ich hab ein Auge auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[56325] = { id = 56325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wendet sich", description = "Wir haben keine Zeit mehr. Wir müssen Golganneths Gezeitenstein unter unsere Kontrolle bringen, und der Wurfspeer ist unsere beste Chance, die Barriere zu durchdringen, die ihn umgibt.\n\nDie Wächterin ist gewaltig, aber wenn wir Azshara besiegen wollen, müssen wir auch sie besiegen. Wir werden unsere gesamten Streitkräfte unten, gleich vor dem Lager, sammeln.\n\nIch würde den Wurfspeer von Suramar gern in Euren Händen wissen, {name}. In der kommenden Schlacht brauchen wir Eure Stärke.", sourceObjective = "Greift das Nagalager an und übernehmt die Kontrolle über Golganneths Gezeitenstein.", completion = "Schnell, der Gezeitenstein!", sourceObjectiveStatus = "unverified-source-field" }
quests[56326] = { id = 56326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung vor den Raben", description = "Ein Rabenschwarm macht Jagd auf die Bürger des Rostbolzens, was wir nicht hinnehmen können!\n\nPrinz Erazmin hat mich gebeten, so viele Bürger wie möglich zu retten, aber ich könnte Eure Unterstützung brauchen. Ich habe die Raben zu diesem Hügel verfolgt. Wir ballern die Raben vom Himmel und Ihr rettet die Mechagnome.\n\nBenutzt mein Markierungsgewehr, wenn Ihr Hilfe dabei braucht, einen der Raben vom Himmel zu holen.", sourceObjective = "Rettet 8 verletzte Mechagnome.", completion = "Ihr seid Eurem Ruf gerecht geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[56327] = { id = 56327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerteilte Bots", description = "Die Verwertung von Bots ist mein Ding! Ich hole aus allen Bots, die Ihr zu meinem Verschrotter bringt, die guten und verwertbaren Teile heraus. Es gibt bei der Sache nur Gewinner!\n\nBenutzt den Botneuauflader, um mir tote Bots zu bringen und ich werde sie in nützliche Einzelteile zerlegen.", sourceObjective = "Bringt 12 wiederbelebte Bots zu Fitz Funkenschlag.", completion = "Diese Ersatzteile sind einfach wunderbar! Ihr könnt hier jederzeit Eure Bots abliefern!", sourceObjectiveStatus = "unverified-source-field" }
quests[56328] = { id = 56328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht zum Verzehr geeignet", description = "Die Troggs beobachten alles, was wir tun.\n\nSie sehen, dass wir Öl in die verschiedenen Maschinen gießen, also stehlen sie das Öl jetzt und trinken es. Ich glaube, sie denken, dass es sie in Maschinen verwandeln wird!\n\nWir brauchen das Öl zurück, bevor sie alles auftrinken!", sourceObjective = "Bergt 12 Behälter mit gestohlenem Öl.", progress = "Holt das Öl zurück, schnell!", completion = "Ihr habt gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[56334] = { id = 56334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bots außer Kontrolle", description = "Er wütet da oben unkontrollierbar!\n\nIch habe ihnen gesagt, sie sollen es nicht tun, aber sie haben nicht auf mich gehört. Jetzt ist er komplett außer Kontrolle und hat alle da oben umgebracht. Er ist der Prototyp eines Wirbelbots. Sie hätten ihn niemals konstruieren sollen!\n\nIhr müsst ihn aufhalten, bevor er hier unten nach weiteren Opfern sucht!\n\nTötet den wirbelnden Zapp-o-Mat.", sourceObjective = "Tötet den wirbelnden Zapp-o-Mat.", completion = "Ihr habt Euch besser geschlagen als die Konstrukteure des Bots.", sourceObjectiveStatus = "unverified-source-field" }
quests[56335] = { id = 56335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt aufladen? Das kostet!", description = "Ihr wollt ein paar Energiezellen an unserem Energieturm aufladen?\n\nDas wundert mich nicht, das wollen alle.\n\nUnd jeder muss dafür ZAHLEN. Habt Ihr das verstanden, oder braucht Ihr eine Wiederholung?\n\n<Flux spuckt hinter sich.>\n\nEs ist wohl das erste Mal für Euch. Für solche Grünschnäbel hat Bondo ein ganz besonderes Angebot.\n\nEine kleine Zugriffsgebühr und nur eine Aufladung.\n\nAbgemacht? Ein besseres Angebot bekommt Ihr nicht.", sourceObjective = "Zahlt Flux' Zugriffsgebühr und nutzt dann die Aufladestation, um die leere Energiezelle aufzuladen.", progress = "Ihr wollt ein paar Energiezellen an unserem Energieturm aufladen?\n\nSpart Euch Eure Tränenmärchen. Jeder muss zahlen.\n\n<Flux spuckt über ihre Schulter.>\n\nKeine Ausnahmen.", completion = "Beschränkter Zugriff gewährt.\n\nLadet auf, was immer Ihr wollt, aber macht nichts kaputt.\n\n<Flux spuckt über ihre Schulter.>\n\nUnd ganz wichtig: Kümmert Euch um Euren eigenen Mist.", sourceObjectiveStatus = "unverified-source-field" }
quests[56336] = { id = 56336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entdeckung der Artefaktfragmente", description = "Die Artefaktfragmente scheinen von den Kreaturen zu stammen, die wir in den Außenbezirken von Ashran gefunden haben. Geht, tötet alle, die Ihr findet, und bringt mindestens fünfzig zum Magier Ecilam am Lagerfeuer in der Sturmschildfeste.", sourceObjective = "Ecilam in der Sturmschildfeste möchte, dass Ihr Kreaturen in den Außenbezirken von Ashran abseits der Hauptstraße tötet und 50 Artefaktfragmente zu ihm bringt.", progress = "Sind das Artefaktfragmente, die ich da sehe?", completion = "Gute Arbeit. Solltet Ihr noch mehr Artefaktfragmente finden, bringt sie mir oder anderen, die sie benötigen, um Euren Beitrag zu den Kriegsanstrengungen zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56337] = { id = 56337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entdeckung der Artefaktfragmente", description = "Die Artefaktfragmente scheinen von den Kreaturen zu stammen, die wir in den Außenbezirken von Ashran gefunden haben.\n\nGeht und tötet alle, die Ihr findet, und bringt mindestens fünfzig Artefaktfragmente zur Magierin Fura im Vorposten des Kriegsspeers.", sourceObjective = "Fura im Vorposten des Kriegsspeers möchte, dass Ihr Kreaturen in den Außenbezirken von Ashran abseits der Hauptstraße tötet und 50 Artefaktfragmente zu ihr bringt.", progress = "Sind das Artefaktfragmente, die ich da sehe?", completion = "Gute Arbeit. Solltet Ihr noch mehr Artefaktfragmente finden, bringt sie mir oder anderen, die sie benötigen, um Euren Beitrag zu den Kriegsanstrengungen zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56338] = { id = 56338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volrath muss sterben!", description = "Die Horde steht dem erfolgreichen Abschluss unserer Mission in Ashran im Weg. Ihr Anführer ist der oberste Kriegsfürst Volrath. Er muss sterben.\n\nKämpft Euch durch die zentrale Straße, infiltriert den Kriegsspeer und tötet Volrath.", sourceObjective = "Tötet den Obersten Kriegsfürsten Volrath, der sich im Hordenlager Kriegsspeer in Ashran befindet.", completion = "Gut gemacht. Die Horde wird es sich zweimal überlegen, sich hier in Ashran mit uns anzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56339] = { id = 56339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tremblade muss sterben!", description = "Diese Schlacht um Ashran dauert schon zu lange an. Die Allianz wird anscheinend von Großmarschall Tremblade angeführt. Wenn sie fällt, wird die Allianz zusammenbrechen.\n\nKämpft Euch durch die zentrale Straße, infiltriert ihre Burg und tötet Tremblade.\n\nFür die Horde!", sourceObjective = "Tötet Großmarschall Tremblade im Allianzlager Burg des Sturmschilds in Ashran.", completion = "So muss das aussehen. Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56341] = { id = 56341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterbräuzahnrad", description = "<Die Dunkeleisenzwerge von Düsterbräu sind geflohen und haben ein kleines Teil von einer ihrer Maulwurfmaschinen zurückgelassen.\n\nVielleicht würden Eure Verbündeten Dunkeleisenzwerge gerne von Eurem Sieg hören.>", sourceObjective = "Sprecht mit Verra Feuerblut auf dem Braufestplatz.", completion = "<Verra spuckt auf das Zahnrad.>\n\nDieser Düsterbräu ist ein Mistkerl. Er war schon ein Quergeist, bevor wir der Allianz beigetreten sind. Es wundert mich nicht, dass er immer noch angreift.\n\nEr denkt nur ans Saufen und daran, Chaos zu verursachen! Ich liebe diese Dinge zwar auch, aber es gibt auch noch andere Sachen im Leben!\n\nDanke, dass Ihr Euch um ihn gekümmert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56344] = { id = 56344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Finsterbrecherzitadelle", description = "Wir haben alle Expeditionsmitglieder außer der Anführerin gerettet. Lindies Späh-o-Matik hat sie vor der Finsterbrecherzitadelle ausgemacht.\n\nMeredy hat einen etwas... interessanten Rettungsplan erdacht. Er könnte unsere einzige Chance sein.\n\nKommt. Wir werden uns in die Schatten der Finsterbrecherzitadelle begeben, wo unsere Rettungsmission beginnt.", sourceObjective = "Trefft Lady Jaina Prachtmeer außerhalb der Finsterbrecherzitadelle.", completion = "In Ordnung, {name}. Ich hoffe, Ihr seid ein guter Schauspieler, denn Euch erwartet ein sehr schwieriges Publikum.", sourceObjectiveStatus = "unverified-source-field" }
quests[56346] = { id = 56346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Technologie", description = "<Angesichts Eurer Erfahrungen mit den Naga und der Macht, über die sie gebieten, fragt Ihr Euch, ob es nicht äußerst vorteilhaft sein könnte, ihre eigene Macht gegen sie einzusetzen.\n\nVielleicht kann Euch Ausbilder Ulooaka in Mezzameer helfen, diesen Kern zu reparieren und ihn im Kampf gegen die Nagainvasoren einzusetzen.>", sourceObjective = "Bringt den beschädigten Energiekern zu Ausbilder Ulooaka in Mezzameer.\n\nBereitgestellter Gegenstand:", completion = "Was bringt Ihr mir denn da?\n\n<Ausbilder Ulooaka inspiziert den beschädigten Energiekern und zieht eine Augenbraue hoch. Ihr fragt ihn, ob sich der Kern vielleicht gegen die Naga einsetzen ließe.>\n\nJa, ich glaube schon. Aber vermutlich nicht so, wie Ihr Euch das vorstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56347] = { id = 56347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine abgrundtiefe Gelegenheit", description = "Ich glaube, wir können mit diesem Ding unsere Rüstungen stärker machen, {name}. Indem wir seine Energie umleiten, können wir die Qualität unseres Handwerks deutlich erhöhen.\n\nAber eins nach dem anderen. Zuerst muss dieses Gerät repariert werden.\n\nDazu brauchen wir allerdings mächtige Materialien, die man für gewöhnlich bei den stärkeren Kreaturen dieser Region findet.\n\nIch glaube, Handwerker Okata ist im Sammeln der Materialien, die wir brauchen, eine echte Kapazität. Ich werde mal bei ihm nachschauen, was er auf Lager hat.", sourceObjective = "Besorgt 15 Abyssalsplitter von Handwerker Okata.", progress = "Wie verläuft die Materialjagd?", completion = "Das dürfte reichen, {name}. Ich fange sofort mit der Reparatur an.", sourceObjectiveStatus = "unverified-source-field" }
quests[56348] = { id = 56348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ewige Palast: Wir können ihn stärker machen...", description = "Das Objekt funktioniert nun. Bei der Reparatur ist mir allerdings klar geworden, dass er sogar noch mehr Energie produzieren könnte.\n\nNatürlich sind dazu noch stärkere Materialien erforderlich, die man meines Wissens nur im Ewigen Palast findet.\n\nAzsharas Armee, und sogar sie selbst, sind mit außergewöhnlich mächtigen Gegenständen ausgestattet. Wenn Ihr mir ein paar davon bringen könntet, werde ich einige Tests durchführen, um meine Theorie zu bestätigen.", sourceObjective = "Sammelt 20 ewige Ornamente von den mächtigsten Kreaturen des Ewigen Palasts.", progress = "Wie läuft die Suche nach diesen Gegenständen?", completion = "Ja, die sind wunderbar. Gut gemacht, {name}.\n\nIch beginne gleich mit der Aufwertung des Kerns.", sourceObjectiveStatus = "unverified-source-field" }
quests[56349] = { id = 56349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ewige Palast: Grenzen austesten", description = "Da wir nun wissen, wie man die Leistung dieses Geräts erhöht, sollten wir seine Kapazitäten noch weiter steigern.\n\nBringt mir noch mehr von diesen Ornamenten. VIEL mehr.\n\nMal sehen, wie viel wir noch aus dem Ding rauskitzeln können.", sourceObjective = "Sammelt 200 ewige Ornamente von den mächtigsten Kreaturen des Ewigen Palasts.", progress = "Schon Glück bei der Beschaffung weiterer Ornamente gehabt?", completion = "Wow, das ist... eine satte Menge!\n\nAlso gut, dann sehen wir mal, was dieses Ding kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[56350] = { id = 56350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärung im Palast", description = "Wir können uns hier nicht ewig verstecken, {name}. Jemand muss sich um Azshara kümmern.\n\nEs wäre töricht, ihren Palast anzugreifen, ohne zu wissen, wie ihre Verteidigungsmaßnahmen dort aussehen. Ich habe in Eurer Abwesenheit einen Spähtrupp entsandt, aber er hat sich noch nicht zurückgemeldet.\n\nDas beunruhigt mich, {name}. Lasst es mich wissen, wenn Ihr bereit seid, und ich werde ein Ritual abhalten, um zu sehen, was mit unseren Spähern passiert ist.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer, um den Spähtrupp zu überwachen.", completion = "Der Gezeitenstein! Natürlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[56351] = { id = 56351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ewige Palast: Grenzen austesten", description = "Da wir nun wissen, wie man die Leistung von diesem Ding erhöht, sollten wir seine Kapazitäten noch weiter steigern.\n\nBringt mir noch mehr von diesen Ornamenten. VIEL mehr.\n\nMal sehen, wie viel wir noch aus dem Ding rauskitzeln können.", sourceObjective = "Sammelt 200 ewige Ornamente von den mächtigsten Kreaturen des Ewigen Palasts.", progress = "Schon Glück bei der Beschaffung weiterer Ornamente gehabt?", completion = "Wow, das ist... eine satte Menge!\n\nAlso gut, dann sehen wir mal, was dieses Ding kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[56352] = { id = 56352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ewige Palast: Wir können ihn stärker machen...", description = "Das Objekt funktioniert nun. Bei der Reparatur ist mir allerdings klar geworden, dass er sogar noch mehr Energie produzieren könnte.\n\nNatürlich sind dazu noch stärkere Materialien erforderlich, die man meines Wissens nur im Ewigen Palast findet.\n\nAzsharas Armee, und sogar sie selbst, sind mit außergewöhnlich mächtigen Gegenständen ausgestattet. Wenn Ihr mir ein paar davon bringen könntet, werde ich einige Tests durchführen, um meine Theorie zu bestätigen.", sourceObjective = "Sammelt 20 ewige Ornamente von den mächtigsten Kreaturen des Ewigen Palasts.", progress = "Wie läuft die Suche nach diesen Gegenständen?", completion = "Ja, die sind wunderbar. Gut gemacht, {name}.\n\nIch beginne gleich mit der Aufwertung des Kerns.", sourceObjectiveStatus = "unverified-source-field" }
quests[56353] = { id = 56353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine abgrundtiefe Gelegenheit", description = "Ich glaube, wir können mit diesem Ding unsere Rüstungen stärker machen, {name}. Indem wir seine Energie umleiten, können wir die Qualität unseres Handwerks deutlich erhöhen.\n\nAber eins nach dem anderen. Zuerst muss dieses Gerät repariert werden.\n\nDazu brauchen wir allerdings mächtige Materialien, die man für gewöhnlich bei den stärkeren Kreaturen dieser Region findet.\n\nIch glaube, Finder Pruc ist im Sammeln der Materialien, die wir brauchen, eine echte Kapazität. Ich werde mal bei ihm nachschauen, was er auf Lager hat.", sourceObjective = "Besorgt 15 Abyssalsplitter von Finder Pruc.", progress = "Wie verläuft die Materialjagd?", completion = "Das dürfte reichen, {name}. Ich fange sofort mit der Reparatur an.", sourceObjectiveStatus = "unverified-source-field" }
quests[56354] = { id = 56354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Technologie", description = "<Angesichts Eurer Erfahrungen mit den Naga und der Macht, über die sie gebieten, fragt Ihr Euch, ob es nicht äußerst vorteilhaft sein könnte, ihre eigene Macht gegen sie einzusetzen.\n\nVielleicht kann Euch Rolm in Neuheim helfen, diesen Kern zu reparieren und ihn im Kampf gegen die Nagainvasoren einzusetzen.>", sourceObjective = "Bringt den beschädigten Energiekern zu Rolm in Neuheim.\n\nBereitgestellter Gegenstand:", completion = "Was bringt Ihr mir denn da?\n\n<Rolm inspiziert den beschädigten Energiekern und zieht eine Augenbraue hoch. Ihr fragt ihn, ob sich der Kern vielleicht gegen die Naga einsetzen ließe.>\n\nJa, ich glaube schon. Aber vermutlich nicht so, wie Ihr Euch das vorstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56355] = { id = 56355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampferprobt", description = "Eine Waffe wie diese könnte im Kampf gegen König Mechagons Truppen wirklich die Wende bringen. Schauen wir mal, wie sich ihre Ausrüstung gegen unser neues Spielzeug schlägt.\n\nSchaltet König Mechagons Wachposten aus, wo immer Ihr auf sie stoßt.", sourceObjective = "Eliminiert 10 aufgerüstete, anodisierte oder korrodierte Wachposten, wo immer Ihr auf sie stoßt.", completion = "So was sehe ich gerne!", sourceObjectiveStatus = "unverified-source-field" }
quests[56356] = { id = 56356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ewige Palast: Schachzug der Königin", description = "Der Weg ist frei. Der Palast erwartet uns, {name}.\n\nIm Inneren halten die Selbstherrlichen Hof mit einem alten Gott. Sie zu besiegen, wird kein leichtes Unterfangen.\n\nVergesst nicht, dass Azshara eine der mächtigsten lebenden Zauberinnen ist. Wir dürfen weder ihre Macht noch ihr strategisches Geschick unterschätzen... Schließlich konnte sie sich tausende Jahre lang auf uns vorbereiten. Nichtsdestotrotz muss sie besiegt werden.\n\nWir sind bereit, wenn Ihr es seid. Sollen wir ihre Einladung endlich annehmen?", sourceObjective = "Besiegt Königin Azshara im Ewigen Palast.", completion = "Das ist erst der Anfang...", sourceObjectiveStatus = "unverified-source-field" }
quests[56358] = { id = 56358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ewige Palast: Schachzug der Königin", description = "Der Weg zum Palast ist nun frei. Wir müssen dieser Bedrohung ein Ende setzen.\n\nKönigin Azshara ist die mächtigste Zauberin, die es gibt. Sie hat schon vor tausenden Jahren Magie gemeistert... lange vor der Geburt unserer Erzmagier.\n\nDennoch müssen wir obsiegen. Andernfalls werden sie und ihr dunkler Meister ganz Azeroth nach Belieben umformen.\n\nChampion, wir müssen Azshara besiegen. Kämpft Ihr mit uns?", sourceObjective = "Besiegt Königin Azshara im Ewigen Palast.", completion = "Sie ist fort, aber es ist noch lange nicht vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[56361] = { id = 56361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Gischtvernebeltes Leinen", sourceObjective = "Bringt 20 Sturmsilbererz zu Gila Kurzschluss.", progress = "Ich habe eine dringende Anfrage von Tüftlermeister Oberfunks erhalten.\n\nDiese Güter werden benötigt!", completion = "Ich danke Euch, {name}. Eure Hilfe wird in unseren Aufzeichnungen festgehalten, damit die Nachwelt sie angemessen würdigen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[56362] = { id = 56362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Gischtvernebeltes Leinen", sourceObjective = "Bringt 20 Sturmsilbererz zu Skaggit.", progress = "Gazlowes Bestellungen sind hier: Er will diesen Krempel so schnell wie möglich.\n\nHabt Ihr was davon?", completion = "Danke für Eure Hilfe.\n\nIch werde dafür sorgen, dass Gazlowe und Prinz Erazmin wissen, woher die Hilfe kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[56363] = { id = 56363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Rasender Tigerfisch", sourceObjective = "Bringt 20 Sturmsilbererz zu Gila Kurzschluss.", progress = "Ich habe eine dringende Anfrage von Tüftlermeister Oberfunks erhalten.\n\nDiese Güter werden benötigt!", completion = "Ich danke Euch, {name}. Eure Hilfe wird in unseren Aufzeichnungen festgehalten, damit die Nachwelt sie angemessen würdigen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[56364] = { id = 56364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Rasender Tigerfisch", sourceObjective = "Bringt 20 Sturmsilbererz zu Skaggit.", progress = "Gazlowes Bestellungen sind hier: Er will diesen Krempel so schnell wie möglich.\n\nHabt Ihr was davon?", completion = "Danke für Eure Hilfe.\n\nIch werde dafür sorgen, dass Gazlowe und Prinz Erazmin wissen, woher die Hilfe kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[56365] = { id = 56365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte zurückspulen", description = "Ihr existiert hier aufgrund einer Zeitanomalie. Ihr müsst aber in Eure eigene Zeit zurückkehren und uns dort helfen.\n\nDie visuelle Holosphäre von dem Tresorbot hier in der Nähe hat die Daten, die wir brauchen, um König Mechagon zu besiegen, bevor er den Mecherschaffer einsetzen kann.\n\nBringt die visuelle Holosphäre in Eurer Realität zu mir. Mit etwas Glück kann ich die Geschichte rückgängig machen und verhindern, dass diese Zeitlinie jemals stattfindet.", sourceObjective = "Liefert die visuelle Holosphäre bei Izira Getriebeschwur im Rostbolzen ab.", completion = "Hoffen wir einfach, dass Eure Lieferung an mich nicht erst diese alternative Realität verursacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56370] = { id = 56370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ei der Daus", description = "Die Naga nutzen diese Höhlen als Brutstätte für ihre tödlichen Tiefennattern.\n\nDiese Schlangen sind deshalb so gefährlich, weil sie von dunkler Leerenmagie durchdrungen sind.\n\nMir müssen dieser Operation ein Ende setzen, bevor es zu spät ist. Die Truppen der Naga sind schon mächtig genug. Ich will gar nicht daran denken, wozu Azshara mit einer Armee aus Tiefennattern imstande wäre.\n\nUnsere einzige Hoffnung besteht darin, die Tiefennatterneier zu zerstören, bevor die Tiere ausschlüpfen.", sourceObjective = "Vernichtet 10 Tiefennatterneier.", completion = "Ihr habt gute Arbeit geleistet, {name}. Wir dürfen nicht zulassen, dass die Naga eine Armee aus mutierten Tiefennattern aufstellen. Wir werden diesen Ort genau im Auge behalten müssen...", sourceObjectiveStatus = "unverified-source-field" }
quests[56371] = { id = 56371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtwelpenschuppe", description = "<Eine nicht voll ausgebildete Schuppe eines jungen Zwielichtwelpen.\n\nEs sind wieder zunehmend mehr Zwielichtdrachen zu sehen. Das erscheint verdächtig.\n\nIhr solltet die Schuppe Eryna zeigen... Vielleicht hat sie in letzter Zeit etwas Auffälliges bemerkt. Ihr findet sie über Grim Batol im Sumpfland.>", sourceObjective = "Zeigt die Schuppe Eryna über Grim Batol im Sumpfland.\n\nBereitgestellter Gegenstand:", completion = "Willkommen. Wie ich sehe, sind Euch die Welpen aufgefallen. Sie sind erst kürzlich aufgetaucht... zusammen mit weiteren Mitgliedern des Schwarms, die von und zur Zitadelle fliegen.\n\nIch habe tief unten tatsächlich ein paar äußerst seltsame Geschehnisse beobachtet.\n\nIch spüre, dass sich eine große Macht manifestiert hat. Vielleicht ist etwas in den Tiefen erwacht? Eines steht jedoch fest: Der Schwarm mobilisiert sich auf jemandes Geheiß.\n\nIch werde meine Erkenntnisse weiterhin an meinen Schwarm und Euren Sprecher weiterleiten. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[56372] = { id = 56372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Ho-zen", description = "<Die Ho-zen wurden erfolgreich vertrieben und das Braufest ist wieder einmal gerettet.\n\nEs stellt sich aber durchaus die Frage, wie die Ho-zen nach Dun Morogh gelangt sind. Vielleicht solltet Ihr jemanden fragen, der sich mit Navigation und Reisen auskennt.>", sourceObjective = "Sprecht mit Arcti auf dem Braufestplatz.", completion = "Nur weil ich auf einem Schiff nach Azeroth gelangt bin, das durch die Sterne flog, heißt das noch lange nicht, dass ich etwas von... Navigation verstehe.\n\nIch habe im Leben noch keinen Ho-zen gesehen, geschweige denn einen mit Flügeln!\n\nVielleicht sind sie ja Händchen haltend durch den Himmel geflogen? Ich kann da wirklich auch nur raten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56373] = { id = 56373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeschluckt", description = "Früher hat es in dem Teich in der Nähe von Glubschaugenrollys nur so gewimmelt, aber seit letzter Woche verschwindet einer nach dem anderen!\n\nEin großer Wasserelementar schluckt alle Fische! Sie leben zwar noch, schwimmen jetzt aber in diesem Elementar herum.\n\nIhr müsst den Elementar töten und drei Glubschaugenrollys fangen, damit ich ihren Zustand untersuchen kann.", sourceObjective = "Tötet den Rollyschlucker und fangt 3 Glubschaugenrollys.", progress = "Habt Ihr diesen Elementar schon getötet?", completion = "Ihr habt heute viele Rollys gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[56374] = { id = 56374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein titanisches Problem", description = "Wir dürfen keine Zeit verschwenden.\n\nOhne die Schmiede des Ursprungs ist Azeroth anfällig für N'Zoths Verderbnis. Und natürlich befindet sich darin auch noch eine Waffe, die alles Leben auf Azeroth auslöschen könnte!\n\nWir müssen gleich zur Schmiede eilen. MUTTER kann hier die Stellung halten.\n\nBeeilt Euch, wir treffen uns dort.", sourceObjective = "Trefft Magni Bronzebart bei den Hallen des Ursprungs in Uldum.", completion = "Ihr seid gerade rechtzeitig gekommen, {name}.\n\nWir werden hier überrannt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56375] = { id = 56375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Ramkahen", description = "Wir müssen wohl einen Moment warten, während MUTTER herausfindet, was wir mit der Schmiede anstellen sollen. In der Zwischenzeit sollten wir sicherstellen, dass hier niemand noch mehr Schaden verursacht.\n\nIhr solltet mit den Tol'vir in Ramkahen sprechen. Ihr habt ihnen doch früher schon mal geholfen, also könnten sie vielleicht diesmal uns dabei helfen, die Schmiede nicht in falsche Hände fallen zu lassen.", sourceObjective = "Trefft König Phaoris in Ramkahen.", completion = "Willkommen in Uldum, {class}.\n\nIch wünschte, die Begrüßung könnte herzlicher ausfallen, aber leider befindet sich mein Volk erneut in einer recht fatalen Lage.", sourceObjectiveStatus = "unverified-source-field" }
quests[56376] = { id = 56376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftretende Bedrohungen", description = "Die Tol'vir sehen den Schutz der titanischen Konstrukte in Uldum als ihre heilige Pflicht. Doch wir werden stets weniger, und jeden Tag müssen wir uns größeren Bedrohungen stellen.\n\nSelbst mit der Kraft unserer neuen Verbündeten können wir die Feinde nicht ewig zurückhalten. Wenn nur einer von ihnen zu große Macht gewinnt, könnte es reichen, um uns zu überwältigen und die Schmiede in Gefahr zu bringen. Und da kommt Eure Hilfe ins Spiel.\n\nSprecht mit Hochkommandant Kamses, um unsere derzeitige Lage einzuschätzen.", sourceObjective = "Schließt einen Angriff in Uldum ab.", completion = "Die Bedrohung hat nachgelassen... zumindest vorerst.\n\nUnsere Späher werden weiter die Bewegungen der Feinde überwachen. Mit ein wenig Glück können wir sie im Zaum halten, bevor sie sich auf die Schmiede stürzen.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56377] = { id = 56377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft schmieden", description = "Danke, dass Ihr mir bei der Schmiede geholfen habt. Es ist ärgerlich, dass N'Zoth so schnell eindringen konnte, aber wenigstens waren wir rechtzeitig da, um ihre komplette Zerstörung zu verhindern!\n\nJetzt müssen wir die Schmiede wieder auf Vordermann bringen. M.U.T.T.E.R. hat bereits an einer Lösung gearbeitet und wir glauben, wir haben einen brauchbaren Plan.", sourceObjective = "Kehrt zu Magni Bronzebart in der Herzkammer zurück und erfahrt vom Schicksal der Schmiede des Ursprungs.", progress = "Ja?", completion = "Sieht so aus, als könnten wir uns auf ein wahres Abenteuer gefasst machen, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[56378] = { id = 56378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vermisste Besatzung", description = "Ich fasse es nicht. Fast die gesamte Flotte... verloren!\n\nWir brauchen da draußen Schiffe, die wichtige Missionen für uns unterstützen, aber wie soll das jetzt noch gehen?\n\nWenn wir uns von diesem Schlag erholen wollen, werde ich meine besten Leute brauchen. Ich weiß, die Chancen stehen schlecht, aber Ihr müsst sie da draußen für mich finden... idealerweise lebend.", sourceObjective = "Findet und rettet die vermissten Besatzungsmitglieder.", completion = "Nun, das ist vermutlich besser als nichts. Machen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[56379] = { id = 56379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vermisste Besatzung", description = "Ich fasse es nicht. Fast die gesamte Flotte... verloren!\n\nWir brauchen da draußen Schiffe, die wichtige Missionen für uns unterstützen, aber wie soll das jetzt noch gehen?\n\nWenn wir uns von diesem Schlag erholen wollen, werde ich meine besten Leute brauchen. Ich weiß, die Chancen stehen schlecht, aber Ihr müsst sie da draußen für mich finden... idealerweise lebend.", sourceObjective = "Findet und rettet die vermissten Besatzungsmitglieder.", completion = "Nun, das ist vermutlich besser als nichts. Machen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[56380] = { id = 56380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Himmel geholt", description = "Eine von König Mechagons älteren Lufteinheiten hat mechanische Probleme und sitzt in der Nähe am Boden fest.\n\nDie Reparaturarbeiten haben bereits begonnen, also müssen wir schnell zuschlagen, um unseren Vorteil zu nutzen.\n\nZerstört die Luftpatrouille XZ-2, bevor sie vollständig repariert wird.", sourceObjective = "Zerstört die Luftpatrouille XZ-2.", completion = "Das ist eine Bedrohung weniger für unsere Truppen!", sourceObjectiveStatus = "unverified-source-field" }
