quests[56400] = { id = 56400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einheit 17" }
quests[56401] = { id = 56401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blitz aus dem Blauen", description = "Ihr habt viel getan, um das Herz von Azeroth zu verstärken, und ich bin stolz, dass die Drachenschwärme ihre Kraft der Sache zur Verfügung stellen konnten.\n\nJetzt ist es Zeit für den blauen Drachenschwarm, dasselbe zu tun.\n\nAls ich von den Essenzen erfuhr, wusste ich, dass noch ein Rest der Macht meines Drachenschwarms dort draußen sein muss. Einige Überreste, die dort kondensiert sind, wo wir einstmals stark waren.\n\nGenau diese Überreste habe ich gefunden. Die Kirin Tor haben ihre Signatur im Nexus isoliert, aber nur, wer das Herz von Azeroth trägt, kann sie beanspruchen.", sourceObjective = "Trefft Kalecgos im Nexus und holt Euch die aufgeladene Schuppe des Blauen Aspekts.", progress = "Die Macht des Herzens von Azeroth erstaunt mich immer wieder.", completion = "Champion, wir vertrauen Euch diese Macht an, weil wir fest daran glauben, dass Ihr Azeroth retten werdet.\n\nSetzt sie zum Guten ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56402] = { id = 56402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Wüstenwanderer", description = "Für einige unserer gefallenen Brüder und Schwestern mag es zu spät sein, aber es ist nicht zu spät, um ihren Familien Trost zu spenden.\n\nJeder Wüstenwanderer hat eine einzigartige Münze bei sich, die seinen Status als Mitglied in unserer Gruppe symbolisiert.\n\nWenn Ihr diese Münzen findet, bringt sie mir bitte. Ich sorge dafür, dass sie den Angehörigen überbracht werden.", sourceObjective = "Sammelt 6 Münzen der Wüstenwanderer.", progress = "Habt Ihr Münzen für mich?", completion = "Ich danke Euch, {name}. Ich werde dafür sorgen, dass sie in die richtigen Hände gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56405] = { id = 56405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wutritzels Konstruktionswahn", description = "Ihr Widerständler vom Rostbolzen imponiert mir. Tüfteln, Bauen, Erforschen.\n\nIhr lasst Eurer Vorstellungskraft freien Lauf und folgt ihr dann mit hemmungsloser Hingabe... egal, wohin sie Euch führt!\n\n<Walton seufzt tief.>\n\nIch vermisse diese Zeit. Hoffentlich erlaubt mir mein Gewissen eines Tages, mit Euch allen dauerhaft an der Oberfläche zu bleiben...\n\nBevor ich nach Mechagon zurückkehre, müssen wir etwas Unglaubliches bauen!\n\nWaren und ich haben zusammen viele zusätzliche Plätze für Konstruktionsprojekte ausgemacht. \n\nKonstruiert mit Kühnheit!", sourceObjective = "Helft beim Bau von Konstruktionsprojekten.", completion = "Das war clevere Konstruktionskunst, {name}.\n\nVerfeinert Euer Handwerk noch weiter und Ihr könnt mich bald als Chefarchitekten ersetzen. Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[56410] = { id = 56410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheiben von Norgannon", description = "König-Mechagon-Einheit besitzt die Norgannonscheibe. Daten sind fehlerhaft. Besitz solcher Daten ist gefährlich.\n\nBitte helft bei der Bergung der fehlerhaften Scheibenfragmente, die durch Mechagons Müllsysteme entsorgt wurden. \n\nLiefert die fehlerhaften Scheibenfragmente bei Datenanalysator L33-SR zur Reinigung ab.", sourceObjective = "Bergt das fehlerhafte Scheibenfragment.", progress = "Holt das fehlerhafte Scheibenfragment zurück.", completion = "Dieses Datenfragment ist jetzt sicher eliminiert.\n\nFalls Ihr zusätzliche Scheiben findet, bringt sie umgehend zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[56419] = { id = 56419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Doppelgang" }
quests[56421] = { id = 56421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rissiger Datenzylinder", description = "<L33-SR sucht nach diesem Gegenstand.>", progress = "Bringt den Gegenstand zu L33-SR.", completion = "Daten erfolgreich gelöscht." }
quests[56422] = { id = 56422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Geisterschwingen", description = "Wir treffen uns dort, wo unsere Reise begann, {name}.\n\nCorin und ich waren seit so vielen Jahren getrennt. Wir haben so viel aufzuholen.\n\nAls Zeichen unserer Dankbarkeit werden wir in der Gegend bleiben, um Euch bei Euren Reisen durch dieses verfluchte Land zu helfen.", sourceObjective = "Kehrt zu Kelya Mondsturz in Zin-Azshari zurück.", completion = "Ich danke Euch, {name}.\n\nDank Eurer Bemühungen haben wir den Seelenfrieden zurückerhalten, der uns so lange gefehlt hat.\n\nMein Vater und ich stehen Euch zu Diensten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56423] = { id = 56423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großes Speicherfragment", description = "<L33-SR sucht nach diesem Gegenstand.>", sourceObjective = "Bringt den Gegenstand zu L33-SR.", completion = "Daten erfolgreich gelöscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56424] = { id = 56424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbedeckte Scheibe", description = "<L33-SR sucht nach diesem Gegenstand.>", sourceObjective = "Bringt den Gegenstand zu L33-SR.", completion = "Daten erfolgreich gelöscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56425] = { id = 56425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versengte Datenscheibe", description = "<L33-SR sucht nach diesem Gegenstand.>", sourceObjective = "Bringt den Gegenstand zu L33-SR.", completion = "Daten erfolgreich gelöscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56429] = { id = 56429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Rücken zur Wand", description = "Das klingt gar nicht gut... Das klingt wie eine Armee!\n\nWir müssen das untersuchen.\n\nVersucht, nicht zu viel Aufmerksamkeit zu erregen, während wir uns das ansehen. Wenn da unten eine Armee ist, müssen wir uns beeilen, um eine Zuflucht zu finden.", sourceObjective = "Dringt mit Lor'themar und Thalyssra weiter in das Innere von Nazjatar vor.", progress = "Diese Naga folgen nur einem Zweck!", completion = "Diese Naga werden schnell lästig.", sourceObjectiveStatus = "unverified-source-field" }
quests[56430] = { id = 56430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwehr im Ableben", description = "<Nachdem Ihr nun etwas Erfahrung mit Zin'anthiden gesammelt habt, rupft Ihr eines ihrer Tentakel vom Hauptkörper. Dabei zieht sich das Tentakel zusammen und rollt sich auf, sodass Ihr nicht mehr an die Blüten an seiner Innenseite herankommt. Vielleicht weiß Rolm mehr über diese Pflanze und wie man ihre Abwehrreaktion umgeht.>", sourceObjective = "Fragt Rolm nach den Tentakeln der Zin'anthide.\n\nBereitgestellter Gegenstand:", completion = "Zin'anthiden sind keine bloßen Pflanzen, {name}. Wenn sie bemerken, dass sie von Räubern bedroht werden, verhalten sie sich wie alle anderen Lebewesen. Sogar nach ihrem Tod bleibt ihr Abwehrmechanismus intakt.\n\nUm ihr Erntepotenzial voll auszuschöpfen, müsst Ihr sie in falscher Sicherheit wiegen. Hier, ich zeige Euch eine Technik, die ich kenne.", sourceObjectiveStatus = "unverified-source-field" }
quests[56431] = { id = 56431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obacht mit dem Osmenit", description = "<Nachdem Ihr auf das Erz eingeschlagen habt, hebt Ihr ein paar Splitter auf, die auf den Boden gefallen sind. Es müsste doch einen Weg geben, mehr aus diesen Vorkommen herauszuholen, ohne so viel Ausschuss zu generieren. Vielleicht weiß Rolm, wie man das Erz besser abbauen kann.>", sourceObjective = "Fragt Rolm nach den Osmenitsplittern.\n\nBereitgestellter Gegenstand:", completion = "Ah, nun, das liegt an der zerbrechlichen Natur des Erzes. Ihr müsst Eure Technik ein wenig anpassen.\n\nVersucht es statt mit harten, schweren Schlägen lieber damit, es genau an der Kante zu treffen, wo das Erz auf den Fels trifft.\n\nÄhnlich, wie man eine Frucht schält. Ich zeige Euch, wie ich es meine...", sourceObjectiveStatus = "unverified-source-field" }
quests[56432] = { id = 56432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staubtrockenes Problem", description = "<Während Ihr auf das Erz einschlagt, fällt Euch auf, dass viel davon zu Staub zerfällt und vor Euch zu Boden rieselt. Die zerfallene Menge ist so groß, dass man daraus etwas herstellen könnte, wenn sie nur ihre Form behielte.\n\nIhr solltet mit Rolm reden und nachfragen, ob man diesen Zerfall verhindern kann.>", sourceObjective = "Fragt Rolm nach dem Osmenitstaub.\n\nBereitgestellter Gegenstand:", completion = "Flöze, in denen sich Osmenit befindet, sind von anderer Struktur als die reinen Vorkommen.\n\nWenn Ihr das gesamte Osmenit eines Flözes erhalten wollt, müsst Ihr das Erz in Ruhe lassen und Euch um den Fels drum herum kümmern.\n\nDas widerspricht eigentlich der normalen Herangehensweise beim Abbauen, aber vertraut mir, das Ergebnis wird Euch überzeugen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56433] = { id = 56433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz ertränken", description = "Die Allianz verfolgt uns weiterhin, aber sie wird unsere Pläne nicht weiter stören. Treibt ihre Champions in ein nasses Grab.", sourceObjective = "Tötet 25 Spielercharaktere der Allianz in Nazjatar bei aktivem Kriegsmodus.", completion = "Die Allianz wird uns auf keinen Fall besiegen, auch hier nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56434] = { id = 56434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Zankfett und Rohtrogg", description = "Verantwortlich für die Verbreitung von Chaos und Verwüstung auf den Halden, was zum Diebstahl von Energiezellen, Ersatzteilen und dem Verzehr von unwahrscheinlichen Mechanohähnchenflügeln ohne Bezahlung geführt hat.\n\nBesondere Vorsicht ist bei Rohtrogg geboten, der lebendigen Dingen gegenüber eine gewalttätige Neigung an den Tag legt.\n\nBeseitigung dieser beiden Verbrecher hat oberste Priorität.", sourceObjective = "Beseitigt Zankfett und Rohtrogg.", completion = "Es wird allmählich Zeit, dass die beiden verschwinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[56436] = { id = 56436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleiner Schädel", description = "<In den gallertartigen Überresten des Schleims findet Ihr ein kleines Skelett.\n\nVielleicht wird jemand im Rostbolzen vermisst.\n\nIhr hebt den Schädel auf, den man vielleicht noch identifizieren kann.>", sourceObjective = "Zeigt den kleinen Schädel Vera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Noch einer? Keine Sorge, hinter diesem Schädel verbirgt sich keine Tragödie. Er ist nicht echt.\n\nAls wir am Anfang diese Skelette fanden, fürchteten wir das Schlimmste. Dass unsere Kinder sich in der Wildnis verlaufen und verschlungen würden!\n\nAber nein, den Kindern geht es gut.\n\nEs ist König Mechagon, der uns quälen will. Wie ich hörte, hat er eine neue Technologie, die er \"Breidimensionaales Schmieden\" nennt. Damit kann er machen, was immer er will.\n\nUnd er hat beschlossen, gefälschte Babyskelette herzustellen.\n\n<Vera schüttelt den Kopf.>\n\nWerft es einfach zu den anderen in den Häcksler.", sourceObjectiveStatus = "unverified-source-field" }
quests[56437] = { id = 56437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostige Röhre", description = "<Der defekte Schrottbot ist jetzt nur noch ein Haufen Metall. Aus seinen Überresten ragt die für ihn typische Röhre heraus.\n\nIhr entfernt die Röhre. Die Einwohner des Rostbolzens scheinen mit Schrott zu handeln, vielleicht möchte sie dort jemand haben.>", sourceObjective = "Zeigt die rostige RöhreVera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Eine Röhre? Eine rostige Röhre. Oh, das wäre doch nicht nötig gewesen!\n\n<Vera lacht und betrachtet die Röhre dann genauer.>\n\nMoment mal, eine 18er Röhre? Wollt Ihr mir sagen, dass der Umfang dieser Röhre 18 Standardeinheiten beträgt? Das ist das, was mein Messgerät mir anzeigt.\n\nHeiliges künstliches Licht, die ist genau richtig für meinen Föhn.\n\nIhr seid der Beste! Also, der beste Röhrenfinder wenigstens.", sourceObjectiveStatus = "unverified-source-field" }
quests[56438] = { id = 56438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinkendes Warnlicht", description = "<Obwohl der Roboter zerstört wurde, blinkt das Warnlicht immer noch.\n\nDies war offenbar einer der wichtigeren Wachposten von König Mechagon. Die Bürger des Rostbolzens wird sein Ableben bestimmt interessieren.>", sourceObjective = "Zeigt das blinkende Warnlicht Vera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Eine Goldumrandung am Sockel. Das muss von dem goldenen Roboter stammen, der in den Außenbezirken der Stadt patrouillierte?\n\nAusgezeichnet. Dieses Ding geht uns schon so lange auf die Nerven, wie ich denken kann.\n\nNicht, weil er uns wirklich erwischt hätte... Darin war er hoffnungslos schlecht.\n\nNein, das Ding marschiert mitten in der Nacht in unsere Stadt und sieht in unsere Zimmer! Stellt Euch vor... Ihr schlaft tief und fest und plötzlich wird das Zimmer in rotes Licht getaucht und da steht ein Roboter und sieht Euch an.\n\nIrgendwann haut er dann wieder ab, aber mal ehrlich... Wie unverschämt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56439] = { id = 56439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanischer Eiersack", description = "<Ihr findet einen mechanischen Eiersack in dem kaputten Spinnenbot.\n\nDas ergibt keinen Sinn, Roboter pflanzen sich so nicht fort.\n\nOder doch?\n\nJemand im Rostbolzen hat vielleicht Antworten.>", sourceObjective = "Zeigt den mechanischen Eiersack Vera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Also, das ist wirklich unheimlich.\n\nVielleicht dachte König Mechagon, wir hätten Angst vor mechanischen Kreaturen, die sich fortpflanzen.\n\nSo etwas zu tun, würde zu ihm passen. Sagt mehr über seine Ängste aus als über unsere.\n\nOder vielleicht... entwickeln die mechanischen Spinnen sich weiter?\n\nKönnen Programme so etwas?\n\n...\n\nBin ich ein Programm?\n\n<Vera setzt sich hin, um nachzudenken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56440] = { id = 56440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dose mit Kleintierspray", description = "<Im Wrack des Roboters findet Ihr eine versiegelte Dose mit Kleintierabwehrspray.\n\nAlles Leben bis hin zu den Ratten auszulöschen erscheint grausam, wäre König Mechagon aber durchaus zuzutrauen.\n\nJemand im Rostbolzen kann vielleicht zusätzliche Einblicke geben.>", sourceObjective = "Zeigt die Dose mit KleintiersprayVera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Ach ja, habt Ihr noch nicht davon gehört? Proklamation 7: König Mechagon hat alles Nichtmechanische, das kleiner als ein Baby ist, für ungesetzlich erklärt.\n\nEr fand das so wichtig, dass es seine SIEBTE Proklamation überhaupt wurde.\n\n<Vera schüttelt den Kopf.>\n\nDer König hasste Käfer, Ratten und alles Unwillkommene, das seinen Weg in eine Stadt finden könnte. Also hat er sie verboten.\n\nEr verhaftete Kaninchen, Eichhörnchen und sogar Fische. Er hielt kurze Prozesse ab, verurteilte sie zur Mechanisierung oder zum Tod oder schickte sie ins Exil.\n\nEr hat diese fliegenden Roboter gebaut, um sich allem anzunehmen, was danach noch übrig geblieben ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[56441] = { id = 56441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gackerbox", description = "<In dem Funken sprühenden, schwelenden Wrack von Einheit 35 findet Ihr einen kleinen, schwarzen Würfel.\n\nEr scheint aus einer metallischen Substanz zu bestehen und wirkt unversehrt.\n\nBei näherer Betrachtung seht Ihr, dass ein Wort in das Metall eingeprägt wurde: \"Gackerbox\".\n\nDieses mechanische Geflügel hatte eine ziemlich merkwürdige Funktionsweise. Jemand im Rostbolzen wird das wahrscheinlich untersuchen wollen.>", sourceObjective = "Zeigt die GackerboxVera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Ist das die Gackerbox von dieser rostigen Einheit 35? Ich hasse das Ding!\n\n<Vera nimmt Euch die Box ab und wirft sie zu Boden. Sie stampft ein paar Mal mit dem Fuß darauf und dann noch einmal, um ganz sicher zu sein.>\n\nJemand hat das Ding darauf programmiert, die Insel jeden Morgen im Morgengrauen zu wecken! Wer macht denn sowas?!\n\n<Vera starrt in Richtung der Stadt.>\n\nWenn Ihr seht, dass dieses Ding noch einmal auftaucht, verpasst ihm von mir auch noch eine.", sourceObjectiveStatus = "unverified-source-field" }
quests[56442] = { id = 56442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defekte Einheit 6", description = "<Einheit 6 liegt nach Eurem Angriff funktionsunfähig herum.\n\nAn diesem mechanischen Frosch ist irgendetwas anders und beunruhigend. Er scheint das Verhalten eines Froschs nachzuahmen, aber auf eine Weise, die irgendwie falsch wirkt.\n\nKeiner der anderen mechanischen Frösche in der Nähe verhält sich so.\n\nStatt nur einen Teil der Einheit zur Untersuchung mitzunehmen, packt Ihr den ganzen Frosch ein. Schließlich ist er nicht besonders groß.>", sourceObjective = "Zeigt die defekte Einheit 6Vera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Ist das eins der mechanischen Kleintiere? Ah, eins von denen aus dunklem Metall.\n\nIch habe noch nie eins aus der Nähe gesehen. Ich habe mich immer davon ferngehalten, weil sie sich für mich nie... richtig angefühlt haben.\n\nNiemand im Rostbolzen weiß, woher sie kamen. Vielleicht hat König Mechagon sie geschickt, um die anderen Kleintiere während ihrer Mechanisierung im Auge zu behalten? Er wäre jemand, der ihre Leiden gern mitangesehen hätte.\n\nDie meisten glauben, sie sind hier, um uns auszuspionieren. Ihr hättet nicht das ganze Ding mit in die Stadt bringen sollen. Schnappt Euch nächstes Mal einfach ein Auge oder eine Leber.", sourceObjectiveStatus = "unverified-source-field" }
